// Dữ liệu 20 bài HSK4 — từ vựng, nghĩa theo bảng từ của Giáo trình chuẩn HSK4 (bản tiếng Việt), chú thích ngữ pháp theo mục lục.
// Hội thoại, câu ví dụ và truyện do app tự viết (không chép từ sách).
const LESSONS=[{"n":1,"zh":"简单的爱情","vi":"Tình yêu giản dị","topic":"Tình yêu và hôn nhân","words":[["爱情","àiqíng","ái tình","tình yêu (nam nữ)"],["不仅","bùjǐn","bất cận","không những, không chỉ"],["从来","cónglái","tòng lai","từ trước đến nay (thường đi với phủ định)"],["法律","fǎlǜ","pháp luật","pháp luật, luật"],["感动","gǎndòng","cảm động","cảm động; làm xúc động"],["刚","gāng","cương","vừa, vừa mới"],["共同","gòngtóng","cộng đồng","chung, cùng nhau"],["够","gòu","cú","đủ"],["互相","hùxiāng","hỗ tương","lẫn nhau"],["即使","jíshǐ","tức sử","cho dù, dù cho"],["加班","jiā bān","gia ban","tăng ca, làm thêm giờ"],["接受","jiēshòu","tiếp thụ","chấp nhận, tiếp nhận"],["开玩笑","kāi wánxiào","khai ngoạn tiếu","nói đùa, đùa"],["浪漫","làngmàn","lãng mạn","lãng mạn"],["俩","liǎ","lưỡng","hai người, cả hai"],["脾气","píqi","tì khí","tính khí, tính nết"],["缺点","quēdiǎn","khuyết điểm","khuyết điểm, thiếu sót"],["深","shēn","thâm","sâu; sâu sắc"],["生活","shēnghuó","sinh hoạt","cuộc sống; sống"],["适合","shìhé","thích hợp","phù hợp"],["熟悉","shúxi","thục tất","quen thuộc, hiểu rõ"],["吸引","xīyǐn","hấp dẫn","hấp dẫn, thu hút"],["羡慕","xiànmù","tiện mộ","ước ao, ngưỡng mộ"],["幸福","xìngfú","hạnh phúc","hạnh phúc"],["性格","xìnggé","tính cách","tính cách, tính nết"],["印象","yìnxiàng","ấn tượng","ấn tượng"],["幽默","yōumò","u mặc","hóm hỉnh, khôi hài"],["原因","yuányīn","nguyên nhân","nguyên nhân"],["自然","zìrán","tự nhiên","tự nhiên; đương nhiên"],["最好","zuìhǎo","tối hảo","tốt nhất là, tốt nhất nên"],["亮","liàng","lượng","sáng; chiếu sáng","*"],["星星","xīngxing","tinh tinh","ngôi sao","*"]],"grammar":[{"t":"Không những… mà còn…","f":"不仅……也 / 还 / 而且……","e":"Nối hai ý tăng tiến: ý sau mạnh hơn ý trước. Nếu hai vế cùng chủ ngữ, chủ ngữ đứng TRƯỚC 不仅; nếu khác chủ ngữ, 不仅 đứng trước chủ ngữ thứ nhất. 也/还 là phó từ nên đứng sau chủ ngữ vế sau, còn 而且 đứng đầu vế sau.","ex":[["他 不仅 很 幽默， 而且 脾气 也 很 好。","Anh ấy không những hài hước mà tính tình cũng rất tốt."],["她 不仅 懂 法律， 还 会 说 三 种 语言。","Cô ấy không chỉ hiểu luật mà còn nói được ba thứ tiếng."],["不仅 我 羡慕 他们 俩， 我 的 朋友们 也 很 羡慕。","Không chỉ tôi ngưỡng mộ hai người họ, bạn bè tôi cũng rất ngưỡng mộ."]]},{"t":"Phó từ 从来","f":"从来 + 不 + V / 从来 + 没(有) + V + 过","e":"从来 = “từ trước đến nay”, hầu như luôn đi với phủ định. 从来不 nói thói quen, nguyên tắc (không bao giờ làm); 从来没…过 nói chưa từng trải qua. Đừng quên 过 sau động từ khi dùng 从来没.","ex":[["他 从来 不 跟 别人 开玩笑。","Anh ấy chẳng bao giờ đùa với người khác."],["我 从来 没 见过 这么 浪漫 的 人。","Tôi chưa bao giờ gặp người nào lãng mạn như vậy."],["我们 结婚 十 年 了， 他 从来 没 对 我 发过 脾气。","Chúng tôi cưới nhau mười năm, anh ấy chưa từng nổi nóng với tôi."]]},{"t":"Phó từ 刚","f":"S + 刚 + V","e":"刚 = “vừa mới”, chỉ việc xảy ra cách đây không lâu. 刚 là phó từ, đứng sau chủ ngữ, trước động từ (khác 刚才 là danh từ thời gian, có thể đứng trước chủ ngữ). Sau 刚 + V thường không thêm 了.","ex":[["我 刚 下班， 还 没 吃 饭 呢。","Tôi vừa tan làm, còn chưa ăn cơm."],["他们 俩 刚 认识 的 时候， 互相 都 不 太 熟悉。","Lúc hai người họ mới quen, chưa hiểu nhau lắm."],["你 刚 来 这 个 城市， 生活 上 有 什么 困难 就 告诉 我。","Bạn vừa đến thành phố này, cuộc sống có khó khăn gì thì cứ nói với tôi."]]},{"t":"Cho dù… cũng…","f":"即使 + giả thiết， S + 也 + …","e":"即使 nêu một tình huống GIẢ ĐỊNH (có thể chưa xảy ra), vế sau dùng 也 để nói kết quả không đổi. 也 đứng sau chủ ngữ của vế sau, không đứng đầu câu. Nếu là sự thật đã xảy ra thì dùng 虽然 chứ không dùng 即使.","ex":[["即使 工作 再 忙， 他 也 每 天 给 妻子 打 电话。","Cho dù công việc bận đến đâu, ngày nào anh ấy cũng gọi điện cho vợ."],["即使 你 不 同意， 我 也 要 试 一下。","Cho dù bạn không đồng ý, tôi cũng phải thử một lần."],["即使 两 个 人 性格 不 一样， 也 可以 很 幸福。","Cho dù hai người tính cách khác nhau, cũng có thể rất hạnh phúc."]]},{"t":"（在）… 上: về mặt…","f":"(在) + N + 上","e":"Khi đi với danh từ trừu tượng (生活、工作、学习、性格…), 在……上 không chỉ vị trí “ở trên” mà có nghĩa “về mặt, trong lĩnh vực”. Cụm này thường đứng đầu câu hoặc sau chủ ngữ, trước động từ; 在 có thể lược bỏ.","ex":[["我们 俩 在 性格 上 很 不 一样。","Hai chúng tôi về mặt tính cách rất khác nhau."],["在 生活 上， 他 很 照顾 我。","Về mặt cuộc sống, anh ấy rất chăm sóc tôi."],["工作 上 的 事， 最好 不要 带 回 家。","Chuyện công việc, tốt nhất đừng mang về nhà."]]}],"dialog":[["A","听说你和男朋友要结婚了？真羡慕你们俩！","Nghe nói cậu với bạn trai sắp cưới à? Ngưỡng mộ hai người quá!"],["B","谢谢！其实我们刚认识的时候，我对他的印象不太深。","Cảm ơn! Thật ra lúc mới quen, mình không có ấn tượng gì sâu sắc về anh ấy."],["A","那后来他是怎么吸引你的？","Vậy sau đó anh ấy thu hút cậu thế nào?"],["B","他不仅很幽默，而且脾气特别好，从来不对我生气。","Anh ấy không chỉ hài hước mà tính tình còn rất tốt, chưa bao giờ giận mình."],["A","你们在生活上有没有不一样的地方？","Hai người về mặt sinh hoạt có chỗ nào khác nhau không?"],["B","当然有。不过即使有问题，我们也会互相理解。","Đương nhiên là có. Nhưng cho dù có chuyện gì, bọn mình cũng sẽ thông cảm cho nhau."],["A","这就是幸福吧！你们俩真的很适合。","Đó chính là hạnh phúc đấy! Hai người thật sự rất hợp nhau."]],"radicals":["黑","音"],"write":["互","仅"],"hz":{"old":["变","普通","新鲜感","祝"],"prov":["",""]}},
{"n":2,"zh":"真正的朋友","vi":"Người bạn thật sự","topic":"Tình bạn","words":[["毕业","bì yè","tất nghiệp","tốt nghiệp"],["差不多","chàbuduō","soa bất đa","gần như, xấp xỉ; na ná"],["重新","chóngxīn","trọng tân","lại từ đầu, lần nữa"],["当","dāng","đương","khi, lúc (当……的时候)"],["短信","duǎnxìn","đoản tín","tin nhắn"],["而","ér","nhi","còn, trong khi đó (chỉ sự đối lập)"],["丰富","fēngfù","phong phú","phong phú; làm phong phú"],["逛","guàng","cuống","dạo, đi dạo (phố, chợ)"],["好像","hǎoxiàng","hảo tượng","giống như, dường như"],["及时","jíshí","cập thời","đúng lúc, kịp thời"],["交","jiāo","giao","kết (bạn); nộp, giao"],["交流","jiāoliú","giao lưu","giao lưu, trao đổi"],["尽管","jǐnguǎn","tận quản","mặc dù, tuy"],["镜子","jìngzi","kính tử","cái gương"],["聚会","jùhuì","tụ hội","buổi họp mặt; tụ tập"],["困难","kùnnan","khốn nan","khó khăn"],["理解","lǐjiě","lý giải","hiểu, thông cảm"],["联系","liánxì","liên hệ","liên hệ"],["麻烦","máfan","ma phiền","phiền phức; làm phiền"],["陪","péi","bồi","đi cùng, ở bên"],["平时","píngshí","bình thời","lúc thường, ngày thường"],["却","què","khước","lại, nhưng lại"],["适应","shìyìng","thích ứng","thích nghi, quen với"],["讨厌","tǎoyàn","thảo yếm","ghét, không thích"],["无聊","wúliáo","vô liêu","buồn chán, vô vị"],["友谊","yǒuyì","hữu nghị","tình bạn"],["真正","zhēnzhèng","chân chính","thật sự, chân chính"],["正好","zhènghǎo","chính hảo","vừa đúng, vừa may, đúng lúc"],["周围","zhōuwéi","chu vi","xung quanh"],["专门","zhuānmén","chuyên môn","chuyên, riêng (để làm gì)"]],"grammar":[{"t":"正好: vừa đúng, vừa lúc","f":"正好 + V / S + 正好 (+ số lượng)","e":"正好 diễn tả sự trùng hợp vừa khéo về thời gian, số lượng, kích cỡ: “vừa may, vừa đúng”. Làm phó từ thì đứng trước động từ; làm tính từ thì đứng cuối câu làm vị ngữ (không cần 很).","ex":[["我 正好 要 去 超市， 我们 一起 走 吧。","Tôi đang định đi siêu thị, mình cùng đi nhé."],["这 双 鞋 我 穿 正好， 不 大 也 不 小。","Đôi giày này tôi đi vừa khít, không to cũng không nhỏ."],["你 来 得 正好， 我们 正在 讨论 聚会 的 事。","Bạn đến đúng lúc lắm, chúng tôi đang bàn chuyện buổi họp mặt."]]},{"t":"差不多: gần như, xấp xỉ","f":"差不多 + số lượng / V; A 和 B 差不多","e":"Làm phó từ, 差不多 đứng trước số lượng hoặc động từ: “gần, khoảng”. Làm tính từ, 差不多 đứng cuối câu: “na ná nhau, gần như nhau”. Người Việt hay đặt 差不多 sau số lượng như “ba năm gần như” — sai.","ex":[["毕业 以后， 我们 差不多 三 年 没 见面 了。","Sau khi tốt nghiệp, chúng tôi gần ba năm không gặp nhau."],["我 和 他 的 爱好 差不多。","Sở thích của tôi và anh ấy gần giống nhau."],["作业 我 差不多 写 完 了， 再 等 我 十 分钟。","Bài tập tôi gần viết xong rồi, đợi tôi thêm mười phút."]]},{"t":"Mặc dù… nhưng vẫn…","f":"尽管 + sự thật，但是 / 可是 / 还是 / 却 + …","e":"尽管 nêu một SỰ THẬT đã có, vế sau nói kết quả trái với mong đợi; vế sau thường có 但是、可是、还是 hoặc 却. Khác 即使 (giả định): 尽管 nói việc có thật.","ex":[["尽管 工作 很 忙， 他 还是 常常 和 朋友 联系。","Mặc dù công việc rất bận, anh ấy vẫn thường liên lạc với bạn bè."],["尽管 我们 住 得 很 远， 但是 友谊 一直 没 变。","Mặc dù chúng tôi sống rất xa nhau, nhưng tình bạn vẫn không thay đổi."],["尽管 遇到 了 很 多 困难， 她 却 从来 不 说 累。","Mặc dù gặp rất nhiều khó khăn, cô ấy chưa bao giờ kêu mệt."]]},{"t":"Phó từ 却","f":"S + 却 + V / A","e":"却 = “lại, nhưng lại”, chỉ sự trái ngược với điều vừa nói. 却 là PHÓ TỪ nên phải đứng sau chủ ngữ, trước động từ; không đứng đầu câu như 但是. Có thể dùng cùng 但是: 但是 + S + 却….","ex":[["他 平时 话 不 多， 却 很 会 关心 朋友。","Ngày thường anh ấy ít nói, nhưng lại rất biết quan tâm bạn bè."],["我 给 他 发 了 短信， 他 却 一直 没 回。","Tôi đã nhắn tin cho anh ấy, nhưng anh ấy mãi không trả lời."],["大家 都 去 逛街 了， 我 却 只 想 在 家 睡觉。","Mọi người đều đi dạo phố, còn tôi lại chỉ muốn ở nhà ngủ."]]},{"t":"Liên từ 而: còn, trong khi đó","f":"Vế 1， 而 + vế 2","e":"而 nối hai vế có ý ĐỐI LẬP, giống “còn…, trong khi đó…” trong tiếng Việt. 而 đứng đầu vế sau, trước chủ ngữ. Thường dùng trong văn viết; khẩu ngữ hay nói 可是/但是.","ex":[["我 喜欢 热闹， 而 她 喜欢 安静。","Tôi thích náo nhiệt, còn cô ấy thích yên tĩnh."],["南方 的 冬天 很 暖和， 而 北方 的 冬天 非常 冷。","Mùa đông miền Nam rất ấm, trong khi mùa đông miền Bắc vô cùng lạnh."],["有的 人 交 朋友 看 钱， 而 真正 的 朋友 只 看 心。","Có người kết bạn vì tiền, còn bạn thật sự chỉ nhìn tấm lòng."]]}],"dialog":[["A","毕业以后，我们差不多五年没见面了吧？","Từ khi tốt nghiệp, chúng mình gần năm năm không gặp rồi nhỉ?"],["B","是啊！今天正好有空，我专门来看看你。","Đúng vậy! Hôm nay vừa may rảnh, mình đến thăm cậu riêng đấy."],["A","还记得吗？我刚来这个城市的时候，很难适应。","Còn nhớ không? Lúc mình mới đến thành phố này, rất khó thích nghi."],["B","记得。尽管有很多困难，你却从来没想过放弃。","Nhớ chứ. Mặc dù có nhiều khó khăn, cậu lại chưa bao giờ nghĩ đến chuyện bỏ cuộc."],["A","那是因为你常常陪我逛街、聊天。没有你，生活会很无聊。","Đó là vì cậu thường đi dạo phố, tán gẫu với mình. Không có cậu, cuộc sống sẽ rất buồn chán."],["B","朋友之间不用怕麻烦。以后有事，你就及时联系我。","Bạn bè với nhau đừng ngại phiền. Sau này có chuyện gì, cậu cứ liên lạc ngay với mình."]],"radicals":["角","鱼"],"write":["丰","却"],"hz":{"old":["不同","感到","街","身边","校园"],"prov":["",""]}},
{"n":3,"zh":"经理对我印象不错。","vi":"Giám đốc có ấn tượng khá tốt về tôi","topic":"Xin việc và phỏng vấn","words":[["安排","ānpái","an bài","sắp xếp"],["本来","běnlái","bản lai","vốn dĩ, lúc đầu; lẽ ra"],["不管","bùguǎn","bất quản","bất kể, bất luận"],["材料","cáiliào","tài liệu","tài liệu, hồ sơ; vật liệu"],["诚实","chéngshí","thành thật","thành thật"],["符合","fúhé","phù hợp","phù hợp, đáp ứng (yêu cầu)"],["负责","fùzé","phụ trách","phụ trách, chịu trách nhiệm"],["改变","gǎibiàn","cải biến","thay đổi"],["感觉","gǎnjué","cảm giác","cảm thấy; cảm giác"],["顾客","gùkè","cố khách","khách hàng"],["紧张","jǐnzhāng","khẩn trương","căng thẳng, hồi hộp"],["另外","lìngwài","lánh ngoại","ngoài ra; khác"],["留","liú","lưu","để lại, giữ lại; ở lại"],["律师","lǜshī","luật sư","luật sư"],["能力","nénglì","năng lực","năng lực, khả năng"],["判断","pànduàn","phán đoạn","phán đoán, đánh giá"],["其次","qícì","kỳ thứ","tiếp theo, thứ hai là"],["收入","shōurù","thu nhập","thu nhập"],["首先","shǒuxiān","thủ tiên","trước hết, trước tiên"],["提供","tígōng","đề cung","cung cấp"],["挺","tǐng","đĩnh","khá, rất (khẩu ngữ)"],["通知","tōngzhī","thông tri","thông báo, báo tin"],["信心","xìnxīn","tín tâm","lòng tin, sự tự tin"],["应聘","yìngpìn","ứng sính","ứng tuyển, xin việc"],["与","yǔ","dữ","và, với"],["约会","yuēhuì","ước hội","hẹn gặp, hẹn hò"],["咱们","zánmen","cha môn","chúng ta (gồm cả người nghe)"],["招聘","zhāopìn","chiêu sính","tuyển dụng"],["正式","zhèngshì","chính thức","chính thức"],["专业","zhuānyè","chuyên nghiệp","chuyên ngành; chuyên nghiệp"],["准时","zhǔnshí","chuẩn thời","đúng giờ"]],"grammar":[{"t":"Phó từ 挺","f":"挺 + A / động từ tâm lý + (的)","e":"挺 = “khá, rất”, dùng nhiều trong khẩu ngữ, mức độ nhẹ hơn 非常. Cuối câu thường có 的. Không nói 很挺 hay 挺很.","ex":[["这 份 工作 的 收入 挺 高 的。","Thu nhập của công việc này khá cao."],["面试 的 时候， 我 挺 紧张 的。","Lúc phỏng vấn, tôi khá hồi hộp."],["经理 挺 喜欢 你 的， 别 担心。","Giám đốc khá thích bạn đấy, đừng lo."]]},{"t":"本来: vốn dĩ, lúc đầu","f":"S + 本来 + V… ，后来 / 现在…","e":"本来 có hai nghĩa: (1) “lúc đầu, vốn định” — sau đó tình hình đã thay đổi; (2) “lẽ ra, vốn dĩ phải thế” — nhấn mạnh điều hiển nhiên (本来就…). 本来 thường đứng sau chủ ngữ, trước động từ.","ex":[["我 本来 想 当 律师， 后来 改变 了 主意。","Lúc đầu tôi định làm luật sư, sau đó đã đổi ý."],["他 本来 不 想 来， 是 我 让 他 来 的。","Vốn dĩ anh ấy không muốn đến, là tôi bảo anh ấy đến."],["这 件 事 本来 就 是 你 负责 的。","Việc này vốn dĩ là do bạn phụ trách mà."]]},{"t":"另外: ngoài ra, khác","f":"另外，… / 另外 + V / 另外 + (的) + N","e":"另外 đứng đầu câu (có dấu phẩy) = “ngoài ra”, bổ sung thêm ý; đứng trước động từ = “làm thêm/làm riêng”; đứng trước danh từ = “… khác”. Không đặt 另外 ở cuối câu.","ex":[["请 你 准备 好 材料。 另外， 别 忘了 带 照片。","Bạn hãy chuẩn bị đủ hồ sơ. Ngoài ra, đừng quên mang ảnh."],["这 个 问题 咱们 另外 找 时间 谈 吧。","Vấn đề này chúng ta tìm thời gian khác bàn nhé."],["我 不 喜欢 这 家 公司， 想 去 另外 一 家。","Tôi không thích công ty này, muốn đến một công ty khác."]]},{"t":"Trước hết… sau đó…","f":"首先……，其次……","e":"Dùng để liệt kê theo thứ tự quan trọng hoặc trình tự: 首先 = “trước hết”, 其次 = “tiếp theo, thứ hai”. Cả hai thường đứng đầu vế câu. Có thể thêm 最后 cho ý cuối cùng.","ex":[["首先， 你 要 准时； 其次， 要 对 顾客 诚实。","Trước hết, bạn phải đúng giờ; sau đó, phải thành thật với khách hàng."],["招聘 的 时候， 我们 首先 看 能力， 其次 看 经验。","Khi tuyển dụng, chúng tôi xem năng lực trước, sau đó mới xem kinh nghiệm."],["首先 感谢 大家 来 参加 会议， 其次 我 介绍 一下 新 同事。","Trước hết cảm ơn mọi người đến dự họp, tiếp theo tôi xin giới thiệu đồng nghiệp mới."]]},{"t":"不管… 都…: bất kể…","f":"不管 + câu hỏi (谁/什么/怎么/A不A/还是)，S + 都 / 也…","e":"不管 = “bất kể, dù… thế nào”: trong mọi điều kiện kết quả không đổi. Vế sau 不管 PHẢI có dạng nghi vấn (谁、什么、怎么样、多…、A不A、A还是B), không dùng câu trần thuật bình thường. Vế sau dùng 都 hoặc 也.","ex":[["不管 结果 怎么样， 我 都 要 试 一下。","Bất kể kết quả thế nào, tôi cũng phải thử."],["不管 顾客 问 什么 问题， 他 都 很 有 耐心。","Bất kể khách hàng hỏi gì, anh ấy đều rất kiên nhẫn."],["不管 刮风 还是 下雨， 他 每 天 都 准时 上班。","Bất kể gió hay mưa, ngày nào anh ấy cũng đi làm đúng giờ."]]}],"dialog":[["A","听说你昨天去应聘了，感觉怎么样？","Nghe nói hôm qua cậu đi phỏng vấn xin việc, cảm thấy thế nào?"],["B","挺好的。本来我很紧张，后来就不紧张了。","Khá tốt. Lúc đầu mình rất hồi hộp, sau đó thì hết."],["A","经理都问了什么？","Giám đốc hỏi những gì?"],["B","首先问了我的专业，其次问我为什么想来他们公司。","Trước tiên hỏi chuyên ngành của mình, sau đó hỏi tại sao mình muốn vào công ty họ."],["A","那他对你的印象怎么样？","Vậy ông ấy có ấn tượng về cậu thế nào?"],["B","他说我很诚实，能力也符合他们的要求。","Ông ấy nói mình rất thành thật, năng lực cũng đáp ứng yêu cầu của họ."],["A","太好了！什么时候能正式上班？","Tuyệt quá! Khi nào thì chính thức đi làm?"],["B","他们说下个星期一通知我。","Họ nói thứ Hai tuần sau sẽ báo cho mình."]],"radicals":["示","羽"],"write":["另","与"],"hz":{"old":["笔试","面试","体育馆"],"prov":["",""]}},
{"n":4,"zh":"不要太着急赚钱。","vi":"Đừng quá vội kiếm tiền","topic":"Công việc và tiền bạc","words":[["按时","ànshí","án thời","đúng giờ, đúng hạn"],["按照","ànzhào","án chiếu","theo, dựa theo"],["保证","bǎozhèng","bảo chứng","đảm bảo, cam đoan"],["不得不","bù dé bù","bất đắc bất","đành phải, không thể không"],["成功","chénggōng","thành công","thành công"],["调查","diàochá","điều tra","điều tra, khảo sát"],["方法","fāngfǎ","phương pháp","phương pháp, cách thức"],["份","fèn","phần","phần, bản (lượng từ cho công việc, báo, tài liệu)"],["感谢","gǎnxiè","cảm tạ","cảm ơn"],["工资","gōngzī","công tư","tiền lương"],["积累","jīlěi","tích lũy","tích lũy"],["计划","jìhuà","kế hoạch","kế hoạch; lên kế hoạch"],["奖金","jiǎngjīn","tưởng kim","tiền thưởng"],["经验","jīngyàn","kinh nghiệm","kinh nghiệm"],["乱","luàn","loạn","lộn xộn, bừa bãi; (làm) bừa"],["甚至","shènzhì","thậm chí","thậm chí"],["生意","shēngyi","sinh ý","việc làm ăn, buôn bán"],["顺利","shùnlì","thuận lợi","thuận lợi, suôn sẻ"],["谈","tán","đàm","nói chuyện, bàn bạc"],["提","tí","đề","nhắc đến, đề cập"],["提前","tíqián","đề tiền","trước thời hạn, sớm hơn"],["提醒","tí xǐng","đề tỉnh","nhắc nhở"],["完全","wánquán","hoàn toàn","hoàn toàn"],["消息","xiāoxi","tiêu tức","tin tức"],["一切","yíqiè","nhất thiết","tất cả"],["以为","yǐwéi","dĩ vi","tưởng là (nhưng thực tế không phải)"],["原来","yuánlái","nguyên lai","ban đầu, trước đây; hóa ra"],["责任","zérèn","trách nhiệm","trách nhiệm"],["知识","zhīshi","tri thức","kiến thức, tri thức"],["赚","zhuàn","trám","kiếm (tiền), lãi"],["并","bìng","tịnh","(trước 不/没) hoàn toàn không, đâu có","*"]],"grammar":[{"t":"以为: tưởng là","f":"S + 以为 + mệnh đề","e":"以为 = “tưởng là”, thường dùng khi suy nghĩ đó SAI so với thực tế, vế sau hay có 没想到/其实/原来. Khi nêu ý kiến, quan điểm bình thường thì dùng 认为 hoặc 觉得, không dùng 以为.","ex":[["我 以为 这 份 工作 很 轻松， 没 想到 每 天 都 要 加班。","Tôi tưởng công việc này nhẹ nhàng, không ngờ ngày nào cũng phải tăng ca."],["大家 都 以为 他 不 来 了， 他 却 按时 到 了。","Mọi người đều tưởng anh ấy không đến nữa, vậy mà anh ấy lại đến đúng giờ."],["我 还 以为 你 已经 知道 这 个 消息 了 呢。","Tôi còn tưởng bạn đã biết tin này rồi chứ."]]},{"t":"原来: ban đầu / hóa ra","f":"原来 + (的) N / 原来 + mệnh đề","e":"原来 có hai cách dùng: (1) “ban đầu, trước đây” — so sánh với bây giờ: 原来的计划、他原来是老师; (2) “hóa ra” — vừa phát hiện ra sự thật, thường đứng đầu câu: 原来是你！","ex":[["他 原来 是 老师， 现在 做 生意。","Trước đây anh ấy là giáo viên, giờ thì làm kinh doanh."],["原来 你 早 就 知道 这 个 消息 了！","Hóa ra bạn đã biết tin này từ lâu rồi!"],["我们 不得不 改变 原来 的 计划。","Chúng tôi đành phải thay đổi kế hoạch ban đầu."]]},{"t":"并 + 不 / 没: hoàn toàn không","f":"S + 并 + 不 / 没(有) + V / A","e":"并 đặt trước 不/没 để nhấn mạnh phủ định, thường để BÁC BỎ một suy nghĩ của người khác hay của chính mình: “đâu có, hoàn toàn không phải”. 并 luôn đứng trước 不/没, không đứng sau.","ex":[["赚钱 并 不 是 工作 的 一切。","Kiếm tiền hoàn toàn không phải là tất cả của công việc."],["我 并 没有 忘记 你 的 话。","Tôi đâu có quên lời bạn nói."],["这 个 方法 看 起来 很 难， 其实 并 不 难。","Phương pháp này trông có vẻ khó, thực ra chẳng khó chút nào."]]},{"t":"Giới từ 按照: theo","f":"按照 + N + V","e":"按照 = “theo, dựa theo” (kế hoạch, yêu cầu, quy định, cách…). Cụm 按照 + N đứng TRƯỚC động từ, khác tiếng Việt hay nói “làm theo kế hoạch” (động từ trước). Sau 按照 thường là danh từ hai âm tiết trở lên.","ex":[["我们 要 按照 计划 完成 工作。","Chúng ta phải hoàn thành công việc theo kế hoạch."],["按照 公司 的 规定， 迟到 三 次 就 没有 奖金。","Theo quy định của công ty, đi muộn ba lần sẽ không có tiền thưởng."],["请 大家 按照 老师 说 的 方法 去 做。","Mời mọi người làm theo phương pháp thầy giáo đã nói."]]},{"t":"甚至: thậm chí","f":"…，甚至 + V / N…","e":"甚至 = “thậm chí”, nêu ra ví dụ nổi bật nhất, mức độ cao nhất. Thường đứng trước động từ hoặc trước chủ ngữ/danh từ được nhấn mạnh, hay đi với 都/也 ở sau.","ex":[["他 工作 太 忙 了， 甚至 周末 也 不 休息。","Anh ấy bận quá, thậm chí cuối tuần cũng không nghỉ."],["这 个 问题 很 简单， 甚至 孩子 都 知道。","Câu hỏi này rất đơn giản, thậm chí trẻ con cũng biết."],["他 很 少 提 自己 的 事， 甚至 好 朋友 也 不 告诉。","Anh ấy hiếm khi nhắc đến chuyện của mình, thậm chí bạn thân cũng không kể."]]}],"dialog":[["A","你刚工作一年，就想换工作了？","Con mới đi làm một năm mà đã muốn đổi việc rồi à?"],["B","原来那家公司工资太低了，我想去一个能多赚点儿钱的地方。","Công ty cũ lương thấp quá, con muốn đến chỗ kiếm được nhiều tiền hơn."],["A","我还以为你很喜欢那份工作呢。","Bố còn tưởng con rất thích công việc đó chứ."],["B","我并不讨厌它，只是觉得奖金太少了。","Con đâu có ghét nó, chỉ thấy tiền thưởng ít quá."],["A","年轻的时候，积累经验和知识比赚钱更重要。","Lúc còn trẻ, tích lũy kinh nghiệm và kiến thức quan trọng hơn kiếm tiền."],["B","您说得对，我会再好好儿考虑一下的。","Bố nói đúng, con sẽ suy nghĩ lại cho kỹ."]],"radicals":["骨","食"],"write":["乱","份"],"hz":{"old":["按","成"],"prov":["",""]}},
{"n":5,"zh":"只买对的，不买贵的。","vi":"Chỉ mua cái đúng, không mua cái đắt","topic":"Mua sắm thông minh","words":[["标准","biāozhǔn","tiêu chuẩn","tiêu chuẩn, chuẩn mực"],["打折","dǎ zhé","đả chiết","giảm giá"],["购物","gòu wù","cấu vật","mua sắm"],["光","guāng","quang","chỉ, chỉ có (= 只)"],["广告","guǎnggào","nghiễm cáo","quảng cáo"],["寄","jì","ký","gửi (thư, hàng)"],["家具","jiājù","gia cụ","đồ nội thất"],["价格","jiàgé","giá cách","giá cả"],["考虑","kǎolǜ","khảo lự","suy xét, cân nhắc"],["肯定","kěndìng","khẳng định","chắc chắn, nhất định; khẳng định"],["浪费","làngfèi","lãng phí","lãng phí, hoang phí"],["流行","liúxíng","lưu hành","thịnh hành, đang mốt"],["年龄","niánlíng","niên linh","tuổi"],["葡萄","pútao","bồ đào","quả nho"],["任何","rènhé","nhậm hà","bất kỳ, bất cứ"],["沙发","shāfā","sa phát","ghế sofa"],["实际","shíjì","thực tế","thực tế; thiết thực"],["实在","shízài","thực tại","thật sự, quả thật"],["受到","shòudào","thụ đáo","nhận được, được (欢迎/影响…)"],["顺便","shùnbiàn","thuận tiện","nhân tiện"],["台","tái","đài","chiếc, cái (lượng từ cho máy móc)"],["味道","wèidào","vị đạo","mùi vị"],["现金","xiànjīn","hiện kim","tiền mặt"],["效果","xiàoguǒ","hiệu quả","hiệu quả"],["样子","yàngzi","dạng tử","kiểu dáng, hình dáng"],["邀请","yāoqǐng","yêu thỉnh","mời"],["艺术","yìshù","nghệ thuật","nghệ thuật; có tính nghệ thuật"],["优点","yōudiǎn","ưu điểm","ưu điểm"],["尤其","yóuqí","vưu kỳ","nhất là, đặc biệt là"],["质量","zhìliàng","chất lượng","chất lượng"],["制冷","zhìlěng","chế lãnh","làm lạnh","*"]],"grammar":[{"t":"肯定: chắc chắn","f":"S + 肯定 + V / A; 肯定的 + N","e":"肯定 làm phó từ = “chắc chắn”, đứng sau chủ ngữ, trước động từ/tính từ, thể hiện người nói rất tin vào phán đoán của mình. Làm tính từ = “khẳng định”: 肯定的回答. Phủ định là 肯定不/肯定没, không nói 不肯定 với nghĩa “chắc chắn không”.","ex":[["这 家 店 的 东西 肯定 不 便宜。","Đồ ở cửa hàng này chắc chắn không rẻ."],["你 放心， 他 肯定 会 按时 来 的。","Bạn yên tâm, anh ấy chắc chắn sẽ đến đúng giờ."],["经理 给 了 我 一 个 肯定 的 回答。","Giám đốc đã cho tôi một câu trả lời khẳng định."]]},{"t":"再说: hơn nữa / để sau hãy tính","f":"…，再说 + lý do bổ sung; … + 再说","e":"(1) Đứng đầu vế sau, 再说 = “hơn nữa, vả lại”, bổ sung thêm một lý do. (2) Đứng cuối câu sau một mốc thời gian/điều kiện, 再说 = “để sau rồi tính”: 明天再说吧.","ex":[["这 个 沙发 太 贵 了， 再说 家 里 也 放 不 下。","Cái sofa này đắt quá, hơn nữa trong nhà cũng không để vừa."],["这 件 事 我们 明天 再说 吧。","Việc này để mai chúng ta tính nhé."],["我 不 想 出去 吃， 太 浪费 钱， 再说 外面 的 菜 味道 也 一般。","Tôi không muốn ra ngoài ăn, tốn tiền quá, vả lại đồ ăn bên ngoài vị cũng bình thường."]]},{"t":"实际 / 实际上: thực tế","f":"实际 (adj) / 实际上 + mệnh đề","e":"实际 làm tính từ = “thiết thực, sát thực tế”: 这个计划不太实际. 实际上 = “trên thực tế, thật ra”, đứng đầu vế câu để nói sự thật khác với vẻ bề ngoài hoặc điều người ta nghĩ.","ex":[["你 的 想法 很 好， 可是 不 太 实际。","Ý tưởng của bạn rất hay, nhưng không thực tế lắm."],["这 件 衣服 看 起来 很 贵， 实际上 正在 打折。","Chiếc áo này trông có vẻ đắt, thực ra đang giảm giá."],["买 东西 要 考虑 实际 的 需要， 不 能 光 看 价格。","Mua đồ phải cân nhắc nhu cầu thực tế, không thể chỉ nhìn giá."]]},{"t":"Đối với… mà nói","f":"对 + người / sự việc + 来说， …","e":"对……来说 = “đối với… mà nói”, nêu góc nhìn của một người hay một nhóm. Phải có đủ 对 và 来说. Người Việt hay bỏ 来 thành 对我说 — đó lại là “nói với tôi”, nghĩa hoàn toàn khác.","ex":[["对 我 来说， 质量 比 价格 更 重要。","Đối với tôi, chất lượng quan trọng hơn giá cả."],["对 老人 来说， 这 种 手机 用 起来 很 方便。","Đối với người già, loại điện thoại này dùng rất tiện."],["对 年轻人 来说， 流行 的 样子 最 有 吸引力。","Đối với người trẻ, kiểu dáng thịnh hành hấp dẫn nhất."]]},{"t":"尤其: nhất là, đặc biệt là","f":"…，尤其 + (是) + N / A","e":"尤其 nêu ra một phần nổi bật nhất trong cả nhóm đã nói trước đó, nên thường đứng ở VẾ SAU, không đứng đầu câu. Trước danh từ thường dùng 尤其是.","ex":[["我 喜欢 吃 水果， 尤其 是 葡萄。","Tôi thích ăn hoa quả, nhất là nho."],["这 里 的 东西 都 很 贵， 尤其 是 家具。","Đồ ở đây đều đắt, đặc biệt là đồ nội thất."],["最近 天气 很 热， 尤其 是 中午。","Dạo này trời rất nóng, nhất là buổi trưa."]]}],"dialog":[["A","这台空调正在打折，价格挺便宜的。","Chiếc điều hòa này đang giảm giá, giá khá rẻ."],["B","便宜的不一定好，我们要考虑质量和制冷效果。","Rẻ chưa chắc đã tốt, mình phải cân nhắc chất lượng và hiệu quả làm lạnh."],["A","广告上说，它的制冷效果特别好。","Quảng cáo nói khả năng làm lạnh của nó đặc biệt tốt."],["B","广告不能全信。对我来说，只买对的，不买贵的。","Quảng cáo không thể tin hết. Với em, chỉ mua cái đúng, không mua cái đắt."],["A","那我们再看看别的吧，再说今天也不一定要买。","Vậy mình xem thêm cái khác đi, vả lại hôm nay cũng chưa chắc phải mua."],["B","好，顺便去家具店看看沙发。","Được, nhân tiện qua cửa hàng nội thất xem sofa luôn."]],"radicals":["齿","革"],"write":["台","尤"],"hz":{"old":["购买","商场","咱","做客"],"prov":["",""]}},
{"n":6,"zh":"一分钱一分货。","vi":"Tiền nào của nấy","topic":"Giá cả và chất lượng","words":[["百分之","bǎi fēn zhī","bách phân chi","phần trăm"],["倍","bèi","bội","lần (gấp bao nhiêu lần)"],["尝","cháng","thường","nếm, nếm thử"],["打扰","dǎrǎo","đả nhiễu","làm phiền, quấy rầy"],["方面","fāngmiàn","phương diện","mặt, phương diện"],["各","gè","các","các, mỗi"],["果汁","guǒzhī","quả trấp","nước ép trái cây"],["好处","hǎochù","hảo xứ","lợi ích, điều tốt"],["活动","huódòng","hoạt động","hoạt động, sự kiện"],["获得","huòdé","hoạch đắc","giành được, đạt được"],["降低","jiàngdī","giáng đê","hạ thấp, giảm"],["竟然","jìngrán","cánh nhiên","vậy mà, không ngờ"],["举办","jǔbàn","cử biện","tổ chức (sự kiện)"],["举行","jǔxíng","cử hành","tổ chức, diễn ra (hội họp, thi đấu…)"],["例如","lìrú","lệ như","ví dụ như"],["满","mǎn","mãn","đầy, đủ, tròn (đạt mức)"],["免费","miǎn fèi","miễn phí","miễn phí"],["内","nèi","nội","bên trong, trong vòng"],["皮肤","pífū","bì phu","da"],["其中","qízhōng","kỳ trung","trong đó"],["轻","qīng","khinh","nhẹ"],["情况","qíngkuàng","tình huống","tình hình, tình huống"],["售货员","shòuhuòyuán","thụ hóa viên","nhân viên bán hàng"],["所有","suǒyǒu","sở hữu","tất cả, toàn bộ"],["袜子","wàzi","miệt tử","tất, vớ"],["西红柿","xīhóngshì","tây hồng thị","cà chua"],["小说","xiǎoshuō","tiểu thuyết","tiểu thuyết"],["修理","xiūlǐ","tu lý","sửa chữa"],["支持","zhīchí","chi trì","ủng hộ"],["值得","zhídé","trị đắc","đáng, xứng đáng"],["会员卡","huìyuánkǎ","hội viên tạp","thẻ hội viên","*"]],"grammar":[{"t":"Phó từ 竟然 (vậy mà, không ngờ)","f":"S + 竟然 + V / A","e":"竟然 diễn tả điều xảy ra trái với dự đoán, khiến người nói bất ngờ: “vậy mà…, không ngờ…”. 竟然 là phó từ nên thường đứng sau chủ ngữ, trước động từ/tính từ; người Việt hay đặt nó lên đầu câu như “Không ngờ anh ấy…” — trong tiếng Trung nên nói 他竟然….","ex":[["这么 便宜 的 袜子， 竟然 穿 了 两 年 还 没 坏。","Đôi tất rẻ thế mà đi hai năm vẫn chưa hỏng."],["他 学 了 三 年 中文， 竟然 没 读 过 一 本 中文 小说。","Anh ấy học tiếng Trung ba năm mà chưa đọc nổi một cuốn tiểu thuyết tiếng Trung nào."],["一 杯 果汁 竟然 要 五十 块！","Một cốc nước ép mà những năm mươi tệ!"]]},{"t":"Cách nói “gấp … lần” với 倍","f":"A 是 B 的 + số + 倍 / A 比 B + A + 了 + số + 倍","e":"“A 是 B 的 3 倍” = A gấp 3 lần B. “比……增加了一倍” nghĩa là tăng thêm 100%, tức là gấp đôi, không phải “tăng một lần”. Người Việt hay dịch máy móc nên cần chú ý: 增加了一倍 = tăng gấp đôi.","ex":[["这 双 皮鞋 的 价格 是 那 双 的 三 倍。","Giá đôi giày da này gấp ba lần đôi kia."],["今年 参加 活动 的 人 比 去年 增加 了 一 倍。","Năm nay số người tham gia sự kiện tăng gấp đôi so với năm ngoái."],["会员卡 用户 的 数量 是 上 个 月 的 两 倍。","Số người dùng thẻ hội viên gấp hai lần tháng trước."]]},{"t":"Động từ 值得 (đáng để)","f":"(很 / 不) 值得 + V","e":"值得 nghĩa là “đáng, xứng đáng (để làm)”. Sau 值得 thường là động từ: 值得买, 值得一看. Phủ định là 不值得, không nói 没值得. Khác tiếng Việt “đáng tiền” — muốn nói vậy thì dùng 这个钱花得值 hoặc 很值得买.","ex":[["这 本 小说 写 得 很 好， 值得 一 看。","Cuốn tiểu thuyết này viết rất hay, đáng để đọc."],["质量 这么 好 的 东西， 贵 一点儿 也 值得 买。","Đồ chất lượng tốt thế này, đắt một chút cũng đáng mua."],["为了 这 点儿 小 事 生气， 不 值得。","Giận vì chuyện nhỏ thế này thì không đáng."]]},{"t":"Đại từ 其中 (trong đó)","f":"Cả nhóm …， 其中 + một phần …","e":"其中 = “trong số đó”, dùng ở vế sau để chỉ một phần của nhóm vừa nhắc ở vế trước. 其中 tự nó đã là “trong đó”, nên không đặt sau danh từ kiểu 学生其中 ✗, cũng không thêm 里 thành 其中里 ✗.","ex":[["我们 班 有 二十 个 学生， 其中 一半 是 女生。","Lớp mình có hai mươi học sinh, trong đó một nửa là nữ."],["这 家 店 有 十 多 种 果汁， 其中 西红柿 汁 卖 得 最 好。","Quán này có hơn mười loại nước ép, trong đó nước ép cà chua bán chạy nhất."],["他 写 过 很 多 小说， 我 最 喜欢 其中 的 一 本。","Anh ấy đã viết nhiều tiểu thuyết, tôi thích nhất một cuốn trong số đó."]]},{"t":"Cấu trúc （在）……下 (dưới…, trong…)","f":"在 + (ai đó 的) + 帮助 / 支持 / 情况 + 下，…","e":"Nói điều kiện, hoàn cảnh dẫn tới kết quả: 在大家的帮助下 (dưới sự giúp đỡ của mọi người), 在这种情况下 (trong tình hình này). Cụm này đứng đầu câu, trước chủ ngữ. Đừng quên chữ 下 ở cuối; người Việt hay nói thiếu thành 在大家的帮助 ✗.","ex":[["在 大家 的 支持 下， 这 次 活动 举办 得 很 成功。","Nhờ sự ủng hộ của mọi người, sự kiện lần này tổ chức rất thành công."],["在 这 种 情况 下， 我们 只 好 降低 价格。","Trong tình hình này, chúng tôi đành phải hạ giá."],["在 老师 的 帮助 下， 她 获得 了 第一 名。","Dưới sự giúp đỡ của thầy, cô ấy đã giành giải nhất."]]}],"dialog":[["A","您好，打扰一下！我们店这个月举办会员活动，所有商品都打八折。","Chào chị, xin làm phiền một chút! Tháng này cửa hàng có chương trình hội viên, tất cả sản phẩm đều giảm hai mươi phần trăm."],["B","是吗？我想买几双袜子。这种袜子竟然要五十块一双？","Vậy à? Tôi muốn mua mấy đôi tất. Loại tất này mà những năm mươi tệ một đôi à?"],["A","它的价格是普通袜子的两倍，不过很轻，穿着舒服，对皮肤也好。","Giá của nó gấp đôi tất thường, nhưng rất nhẹ, đi êm chân, lại tốt cho da."],["B","一分钱一分货。要是质量好，贵一点儿也值得买。","Tiền nào của nấy. Nếu chất lượng tốt thì đắt một chút cũng đáng mua."],["A","办会员卡是免费的，有了卡还能再便宜百分之十。","Làm thẻ hội viên miễn phí, có thẻ còn được rẻ thêm mười phần trăm."],["B","好，那我办一张。这几种颜色里，哪种卖得最好？","Được, vậy tôi làm một thẻ. Mấy màu này, màu nào bán chạy nhất?"],["A","我们有五种颜色，其中黑色卖得最好。","Chúng tôi có năm màu, trong đó màu đen bán chạy nhất."],["B","那就给我拿三双黑色的吧。","Vậy lấy cho tôi ba đôi màu đen nhé."]],"radicals":["隹","豆"],"write":["内","尝"],"hz":{"old":["购","货","价钱","小朋友","折"],"prov":["",""]}},
{"n":7,"zh":"最好的医生是自己。","vi":"Bác sĩ giỏi nhất là chính mình","topic":"Sức khỏe và lối sống","words":[["擦","cā","sát","lau, chùi"],["超过","chāoguò","siêu quá","vượt quá"],["抽烟","chōu yān","trừu yên","hút thuốc"],["出现","chūxiàn","xuất hiện","xuất hiện, nảy sinh"],["窗户","chuānghu","song hộ","cửa sổ"],["大夫","dàifu","đại phu","bác sĩ"],["掉","diào","điệu","rơi; mất, hết (sau động từ)"],["动作","dòngzuò","động tác","động tác"],["肚子","dùzi","đỗ tử","bụng"],["烦恼","fánnǎo","phiền não","buồn phiền, phiền muộn"],["反对","fǎnduì","phản đối","phản đối"],["感情","gǎnqíng","cảm tình","tình cảm"],["估计","gūjì","cổ kế","đoán chừng, ước tính"],["后悔","hòuhuǐ","hậu hối","hối hận"],["减肥","jiǎn féi","giảm phì","giảm cân"],["教授","jiàoshòu","giáo thụ","giáo sư"],["咳嗽","késou","khái thấu","ho"],["空气","kōngqì","không khí","không khí"],["来不及","láibují","lai bất cập","không kịp"],["气候","qìhòu","khí hậu","khí hậu"],["散步","sàn bù","tản bộ","đi dạo"],["数字","shùzì","số tự","con số"],["帅","shuài","soái","đẹp trai, ngầu"],["说明","shuōmíng","thuyết minh","giải thích; cho thấy"],["辛苦","xīnkǔ","tân khổ","vất vả, cực nhọc"],["严重","yánzhòng","nghiêm trọng","nghiêm trọng, nặng"],["研究","yánjiū","nghiên cứu","nghiên cứu"],["要是","yàoshi","yếu thị","nếu, nếu như"],["植物","zhíwù","thực vật","thực vật, cây cối"],["指","zhǐ","chỉ","chỉ, ý nói đến"],["既","jì","ký","đã… lại…, vừa… vừa… (đi với 又/也/还)","*"],["精神","jīngshén","tinh thần","tinh thần; khỏe khoắn","*"],["流血","liú xiě","lưu huyết","chảy máu","*"]],"grammar":[{"t":"Động từ 估计 (đoán chừng)","f":"(S +) 估计 + mệnh đề","e":"估计 = “đoán chừng, chắc là” dựa trên tình hình trước mắt. Theo sau là cả một mệnh đề. Có thể đứng đầu câu (估计他不来了) hoặc sau chủ ngữ (我估计…). Không nói 我估计是 + danh từ một mình mà phải có vị ngữ rõ ràng.","ex":[["路上 堵车， 估计 他 要 晚 半 个 小时 到。","Đường kẹt xe, chắc anh ấy sẽ đến muộn nửa tiếng."],["我 估计 这 次 报名 的 人 会 超过 一千。","Tôi đoán lần này số người đăng ký sẽ vượt quá một nghìn."],["你 咳嗽 得 这么 严重， 估计 是 感冒 了。","Bạn ho nặng thế này, chắc là bị cảm rồi."]]},{"t":"来不及 / 来得及 (không kịp / kịp)","f":"(还) 来不及 / 来得及 + V","e":"来不及 = không còn đủ thời gian (để làm gì), 来得及 = vẫn kịp. Có thể đứng cuối câu hoặc đi trước một động từ. Phủ định đã nằm trong 不, nên không nói 没来不及 ✗; hỏi thì dùng 来得及吗？","ex":[["快 走 吧， 再 不 走 就 来不及 了。","Đi nhanh lên, không đi nữa là không kịp đâu."],["早上 起 晚 了， 我 来不及 吃 早饭 就 出门 了。","Sáng dậy muộn, tôi không kịp ăn sáng đã phải ra khỏi nhà."],["别 着急， 现在 去 还 来得及。","Đừng vội, bây giờ đi vẫn còn kịp."]]},{"t":"Lặp lại động từ ly hợp (散散步, 聊聊天)","f":"AB → AAB (散步 → 散散步)","e":"Động từ ly hợp (động từ + tân ngữ như 散步, 聊天, 洗澡, 帮忙) khi lặp lại để diễn tả “làm một chút, làm cho thư thả” chỉ lặp chữ đầu: 散散步, 聊聊天. Không lặp cả từ kiểu 散步散步 ✗ như động từ thường (研究研究).","ex":[["吃 完 晚饭， 我们 去 公园 散散步 吧。","Ăn tối xong, mình ra công viên đi dạo một chút nhé."],["周末 在 家 洗洗澡、 聊聊天， 很 放松。","Cuối tuần ở nhà tắm rửa, trò chuyện, rất thư giãn."],["你 来 帮帮忙， 把 窗户 擦 一下。","Bạn lại giúp một tay, lau cửa sổ một chút đi."]]},{"t":"Liên từ 要是 (nếu như)","f":"要是 + điều kiện (的话)，(S +) 就 + kết quả","e":"要是 nghĩa như 如果 (nếu), nhưng mang tính khẩu ngữ hơn. Vế sau thường có 就. Người Việt hay quên 就 hoặc đặt 就 trước chủ ngữ: phải nói 我就…, không nói 就我… ✗.","ex":[["要是 你 明天 有 空儿， 我们 就 一起 去 看 王 教授 吧。","Nếu mai bạn rảnh, mình cùng đi thăm giáo sư Vương nhé."],["要是 再 抽烟， 你 的 咳嗽 会 越来越 严重。","Nếu còn hút thuốc nữa, cơn ho của anh sẽ ngày càng nặng."],["要是 早 知道 这样， 我 就 不 买 了， 真 后悔。","Nếu biết sớm thế này thì tôi đã không mua, hối hận quá."]]},{"t":"Cấu trúc 既……又 / 也 / 还……","f":"S + 既 + A，又 / 也 / 还 + B","e":"既……又…… = “vừa… vừa…, đã… lại…”, nối hai tính chất hoặc hai hành động cùng có. 既 đứng sau chủ ngữ; hai vế nên có cấu trúc giống nhau (cùng là tính từ, hoặc cùng là động từ). Không đặt 既 lên trước chủ ngữ.","ex":[["这 种 运动 既 能 减肥， 又 能 让 人 更 有 精神。","Môn thể thao này vừa giúp giảm cân, lại giúp người ta khỏe khoắn hơn."],["他 既 是 我们 的 教授， 也 是 我们 的 好 朋友。","Ông ấy vừa là giáo sư của chúng tôi, vừa là bạn tốt của chúng tôi."],["散步 既 不 花 钱， 还 对 身体 好。","Đi dạo vừa không tốn tiền, lại tốt cho sức khỏe."]]}],"dialog":[["A","你哪儿不舒服？","Anh thấy khó chịu ở đâu?"],["B","大夫，我最近老是咳嗽，晚上也睡不好。","Thưa bác sĩ, dạo này tôi ho suốt, buổi tối cũng ngủ không ngon."],["A","你抽烟吗？一天抽多少？","Anh có hút thuốc không? Một ngày hút bao nhiêu?"],["B","抽，一天差不多一包，有时候超过一包。","Có ạ, một ngày khoảng một bao, có lúc hơn một bao."],["A","我估计你的咳嗽就是抽烟引起的。要是再不少抽，情况会更严重。","Tôi đoán cơn ho của anh là do hút thuốc gây ra. Nếu không hút ít đi, tình hình sẽ nặng hơn."],["B","我也知道，可是工作压力太大了。","Tôi cũng biết, nhưng áp lực công việc lớn quá."],["A","你既要少抽烟，又要多运动。晚饭后出去散散步吧。","Anh vừa phải hút ít thuốc, vừa phải vận động nhiều. Ăn tối xong ra ngoài đi dạo một chút đi."],["B","好的，我听您的。","Vâng, tôi nghe lời bác sĩ."]],"radicals":["辛","鬼"],"write":["帅","掉"],"hz":{"old":["保","处","加","纸"],"prov":["",""]}},
{"n":8,"zh":"生活中不缺少美。","vi":"Cuộc sống không thiếu cái đẹp","topic":"Thái độ sống tích cực","words":[["成为","chéngwéi","thành vi","trở thành"],["大使馆","dàshǐguǎn","đại sứ quán","đại sứ quán"],["到处","dàochù","đáo xứ","khắp nơi"],["堵车","dǔ chē","đổ xa","kẹt xe, tắc đường"],["发生","fāshēng","phát sinh","xảy ra"],["放松","fàngsōng","phóng tùng","thả lỏng, thư giãn"],["回忆","huíyì","hồi ức","nhớ lại; kỷ niệm"],["积极","jījí","tích cực","tích cực"],["景色","jǐngsè","cảnh sắc","phong cảnh, cảnh vật"],["距离","jùlí","cự ly","khoảng cách; cách (bao xa)"],["科学","kēxué","khoa học","khoa học"],["耐心","nàixīn","nại tâm","kiên nhẫn; sự nhẫn nại"],["巧克力","qiǎokèlì","xảo khắc lực","sô-cô-la"],["亲戚","qīnqi","thân thích","họ hàng"],["缺少","quēshǎo","khuyết thiểu","thiếu"],["伤心","shāng xīn","thương tâm","đau lòng, buồn"],["生命","shēngmìng","sinh mệnh","sự sống, sinh mạng"],["师傅","shīfu","sư phó","bác, chú, thầy (gọi người có tay nghề)"],["使","shǐ","sử","khiến, làm cho"],["态度","tàidù","thái độ","thái độ"],["特点","tèdiǎn","đặc điểm","đặc điểm"],["往往","wǎngwǎng","vãng vãng","thường thường, thường hay"],["心情","xīnqíng","tâm tình","tâm trạng"],["压力","yālì","áp lực","áp lực"],["阳光","yángguāng","dương quang","ánh nắng; tươi sáng, lạc quan"],["因此","yīncǐ","nhân thử","vì vậy, do đó"],["愉快","yúkuài","du khoái","vui vẻ"],["证明","zhèngmíng","chứng minh","chứng minh"],["只要","zhǐyào","chỉ yếu","chỉ cần, miễn là"]],"grammar":[{"t":"Động từ 使 (khiến, làm cho)","f":"A + 使 + B + V / A","e":"使 nghĩa là “khiến cho, làm cho” ai đó có cảm xúc hoặc thay đổi gì. Nghĩa gần với 让 nhưng trang trọng hơn, hay dùng trong văn viết. Khác 让: 使 không có nghĩa “cho phép” hay “bảo ai làm gì”, nên không nói 妈妈使我去买菜 ✗.","ex":[["这 次 旅行 使 我 放松 了 很 多。","Chuyến du lịch này khiến tôi thư giãn hơn nhiều."],["阳光 和 音乐 往往 能 使 人 心情 愉快。","Ánh nắng và âm nhạc thường làm người ta vui vẻ."],["他 的 话 使 大家 都 很 伤心。","Lời anh ấy nói khiến mọi người đều rất buồn."]]},{"t":"Cấu trúc 只要……就……","f":"只要 + điều kiện，(S +) 就 + kết quả","e":"只要…就… = “chỉ cần… là…”: có điều kiện này là đủ để có kết quả. Đừng nhầm với 只有…才… (“chỉ có… mới…”, điều kiện bắt buộc duy nhất). Không dùng 只要 đi với 才.","ex":[["只要 有 耐心， 你 就 一定 能 学 好 汉语。","Chỉ cần có kiên nhẫn, bạn nhất định sẽ học tốt tiếng Trung."],["只要 不 堵车， 二十 分钟 就 能 到 大使馆。","Chỉ cần không kẹt xe, hai mươi phút là đến được đại sứ quán."],["只要 态度 积极， 压力 再 大 也 不 怕。","Chỉ cần thái độ tích cực, áp lực lớn mấy cũng không sợ."]]},{"t":"Cách đáp 可不是 (chứ còn gì nữa)","f":"A: nhận xét …  B: 可不是，…","e":"可不是 dùng để đáp lại, đồng ý hoàn toàn với điều người kia vừa nói: “đúng thế, chứ còn gì nữa”. Dù có chữ 不 nhưng nghĩa là đồng ý, không phải phản đối. Chỉ dùng trong khẩu ngữ, đứng đầu câu trả lời.","ex":[["—— 今天 又 堵车 了。 —— 可不是， 我 在 路上 等 了 一 个 小时。","— Hôm nay lại kẹt xe rồi. — Chứ còn gì nữa, tôi chờ trên đường cả tiếng."],["—— 这儿 的 景色 真 美！ —— 可不是， 我 拍 了 好 多 照片。","— Cảnh ở đây đẹp thật! — Đúng thế, mình chụp bao nhiêu là ảnh."],["—— 最近 工作 压力 太 大 了。 —— 可不是， 我 每天 都 很 晚 才 下班。","— Dạo này áp lực công việc lớn quá. — Đúng vậy, ngày nào tôi cũng tan làm rất muộn."]]},{"t":"Liên từ 因此 (vì vậy, do đó)","f":"Nguyên nhân，因此 + kết quả","e":"因此 đứng đầu vế sau để nêu kết quả, mang sắc thái văn viết, trang trọng hơn 所以. Có thể đi với 由于 ở vế trước (由于……，因此……), nhưng không dùng 因此 và 所以 cùng lúc.","ex":[["他 每天 坚持 运动， 因此 身体 一直 很 好。","Anh ấy kiên trì tập thể dục mỗi ngày, vì vậy sức khỏe luôn rất tốt."],["这 个 城市 到处 是 公园， 因此 成为 了 很 多 人 喜欢 的 地方。","Thành phố này khắp nơi là công viên, do đó trở thành nơi nhiều người yêu thích."],["她 回忆 起 很 多 小时候 的 事， 因此 有点儿 伤心。","Cô ấy nhớ lại nhiều chuyện hồi nhỏ, vì thế có hơi buồn."]]},{"t":"Phó từ 往往 (thường thường)","f":"S + 往往 + V","e":"往往 nói về quy luật, điều thường xảy ra trong những tình huống nhất định (dựa trên kinh nghiệm đã có). Khác 常常: 往往 không dùng cho ý định trong tương lai và cần có điều kiện/tình huống đi kèm; không nói 我以后往往来 ✗, phải nói 我以后常常来.","ex":[["周末 去 公园 散步 的 人 往往 很 多。","Cuối tuần người đi dạo công viên thường rất đông."],["心情 不 好 的 时候， 人 往往 想 吃 甜 的 东西。","Khi tâm trạng không tốt, người ta thường muốn ăn đồ ngọt."],["太 便宜 的 东西， 质量 往往 不 好。","Đồ quá rẻ thì chất lượng thường không tốt."]]}],"dialog":[["A","又堵车了！每天上下班都这样，真让人心情不好。","Lại kẹt xe rồi! Ngày nào đi làm về cũng thế, thật khiến người ta bực mình."],["B","可不是！不过你看窗外，今天的阳光多好。","Chứ còn gì nữa! Nhưng cậu nhìn ra ngoài cửa sổ xem, nắng hôm nay đẹp biết bao."],["A","你总是这么积极。工作压力那么大，你怎么一点儿也不着急？","Cậu lúc nào cũng tích cực thế. Áp lực công việc lớn như vậy, sao cậu chẳng sốt ruột chút nào?"],["B","着急也没用。只要换个态度，堵车的时候也能放松一下。","Sốt ruột cũng vô ích. Chỉ cần đổi thái độ, lúc kẹt xe cũng có thể thư giãn một chút."],["A","怎么放松？","Thư giãn kiểu gì?"],["B","听听音乐，看看路边的景色，或者吃块巧克力。","Nghe nhạc, ngắm cảnh bên đường, hoặc ăn một miếng sô-cô-la."],["A","有道理。生活中往往不是缺少美，而是缺少发现美的眼睛。","Có lý. Trong cuộc sống thường không phải thiếu cái đẹp, mà là thiếu đôi mắt biết phát hiện cái đẹp."],["B","说得好！你的话使我的心情也好多了。","Nói hay lắm! Lời cậu nói khiến tâm trạng mình cũng tốt hơn nhiều."]],"radicals":["里","非"],"write":["态","伤"],"hz":{"old":["长期","窗","得到","堵","美","女性"],"prov":["",""]}},
{"n":9,"zh":"阳光总在风雨后。","vi":"Sau cơn mưa trời lại sáng","topic":"Thất bại và kiên trì","words":[["饼干","bǐnggān","bính can","bánh quy"],["当时","dāngshí","đương thời","lúc đó, khi ấy"],["得","děi","đắc","phải, cần phải"],["放弃","fàngqì","phóng khí","từ bỏ, bỏ cuộc"],["国际","guójì","quốc tế","quốc tế"],["过程","guòchéng","quá trình","quá trình"],["汗","hàn","hãn","mồ hôi"],["坚持","jiānchí","kiên trì","kiên trì, giữ vững"],["结果","jiéguǒ","kết quả","kết quả; kết quả là"],["经历","jīnglì","kinh lịch","trải qua; trải nghiệm"],["可是","kěshì","khả thị","nhưng, thế nhưng"],["理想","lǐxiǎng","lý tưởng","lý tưởng, ước mơ"],["难道","nándào","nan đạo","lẽ nào, chẳng lẽ (câu hỏi tu từ)"],["篇","piān","thiên","bài (lượng từ cho bài văn, bài báo)"],["轻松","qīngsōng","khinh tùng","nhẹ nhàng, thoải mái"],["区别","qūbié","khu biệt","sự khác biệt; phân biệt"],["取","qǔ","thủ","lấy, rút (tiền); giành được"],["失败","shībài","thất bại","thất bại"],["随便","suíbiàn","tùy tiện","tùy ý, qua loa"],["通过","tōngguò","thông qua","thông qua, nhờ; vượt qua (kỳ thi)"],["网球","wǎngqiú","võng cầu","quần vợt"],["许多","xǔduō","hứa đa","rất nhiều"],["赢","yíng","doanh","thắng"],["勇敢","yǒnggǎn","dũng cảm","dũng cảm, gan dạ"],["暂时","zànshí","tạm thời","tạm thời"],["正确","zhèngquè","chính xác","đúng, chính xác"],["至少","zhìshǎo","chí thiểu","ít nhất"],["主意","zhǔyi","chủ ý","ý kiến, ý tưởng"],["总结","zǒngjié","tổng kết","tổng kết, rút kinh nghiệm"],["作家","zuòjiā","tác gia","nhà văn"],["面对","miànduì","diện đối","đối mặt","*"]],"grammar":[{"t":"Câu hỏi tu từ với 难道","f":"难道 + (S +) V / 不 + V + 吗？","e":"难道…吗？ = “chẳng lẽ…, lẽ nào…?” Đây là câu hỏi tu từ để nhấn mạnh, người nói đã biết câu trả lời: câu khẳng định mang nghĩa phủ định và ngược lại. 难道 có thể đứng trước hoặc sau chủ ngữ, cuối câu thường có 吗.","ex":[["难道 你 想 现在 就 放弃 吗？","Chẳng lẽ bạn muốn bỏ cuộc ngay bây giờ sao?"],["这么 简单 的 问题， 你 难道 不 会 吗？","Câu hỏi đơn giản thế này, lẽ nào bạn không biết làm?"],["失败 一 次 就 不 能 再 试 了 吗？ 难道 你 忘 了 自己 的 理想？","Thất bại một lần là không thể thử lại sao? Chẳng lẽ bạn quên ước mơ của mình rồi?"]]},{"t":"通过 (thông qua, nhờ; vượt qua)","f":"通过 + cách thức / sự việc，S + V…  |  通过 + kỳ thi","e":"Giới từ 通过 nêu phương tiện, con đường để đạt kết quả: “thông qua, nhờ”. Cụm 通过… thường đứng đầu câu. 通过 còn là động từ “vượt qua, thi đỗ”: 通过考试. Người Việt hay dùng 用 ở đây, nhưng 用 chỉ dùng cho công cụ cụ thể (用笔写), còn cách thức, hoạt động thì dùng 通过.","ex":[["通过 这 次 比赛， 我 认识 了 许多 朋友。","Thông qua cuộc thi lần này, tôi quen được rất nhiều bạn."],["通过 总结 失败 的 经历， 他 找到 了 正确 的 方法。","Nhờ tổng kết những lần thất bại, anh ấy đã tìm ra phương pháp đúng."],["她 终于 通过 了 国际 汉语 考试。","Cuối cùng cô ấy đã vượt qua kỳ thi tiếng Trung quốc tế."]]},{"t":"Liên từ 可是 (nhưng)","f":"(虽然) …，可是 + (S +) 也 / 还 / 却 …","e":"可是 nối hai vế trái ngược nhau, nghĩa giống 但是 (nhưng), dùng nhiều trong khẩu ngữ. Có thể đi với 虽然 ở vế trước. 可是 đứng đầu vế sau, trước chủ ngữ; đừng đặt sau chủ ngữ như 我可是… (cách đó mang nghĩa nhấn mạnh khác).","ex":[["我 很 想 去 打 网球， 可是 今天 得 加班。","Tôi rất muốn đi đánh quần vợt, nhưng hôm nay phải tăng ca."],["虽然 过程 很 辛苦， 可是 结果 很 好。","Tuy quá trình rất vất vả, nhưng kết quả rất tốt."],["这 篇 文章 很 长， 可是 读 起来 很 轻松。","Bài viết này rất dài, nhưng đọc lên rất nhẹ nhàng."]]},{"t":"结果 (kết quả là…)","f":"Sự việc，结果 + kết cục","e":"结果 đứng đầu vế sau, nêu kết cục cuối cùng của sự việc, thường là điều không mong muốn hoặc bất ngờ: “kết quả là, rốt cuộc”. 结果 còn là danh từ “kết quả” (比赛的结果). Khác 所以: 结果 nhấn vào kết cục xảy ra sau đó, không nhấn vào quan hệ nhân quả.","ex":[["他 没 好好儿 准备， 结果 考试 没 通过。","Anh ấy không chuẩn bị kỹ, kết quả là thi trượt."],["我们 都 以为 会 输， 结果 赢 了。","Ai cũng tưởng sẽ thua, rốt cuộc lại thắng."],["比赛 的 结果 明天 才 能 知道。","Kết quả cuộc thi mai mới biết được."]]},{"t":"Bổ ngữ 上 (đạt được; bắt đầu)","f":"V + 上 (+ O)：考上, 爱上, 住上","e":"上 đặt sau động từ để chỉ đạt được mục tiêu khó khăn (考上大学 = thi đỗ đại học, 住上大房子 = được ở nhà to) hoặc bắt đầu một trạng thái và kéo dài (爱上, 喜欢上 = bắt đầu yêu/thích). Phủ định dùng 没 + V + 上; dạng khả năng: V得上 / V不上.","ex":[["经过 一 年 的 努力， 他 终于 考 上 了 理想 的 大学。","Sau một năm cố gắng, cuối cùng anh ấy đã đỗ vào trường đại học mơ ước."],["来 中国 以后， 她 爱 上 了 中国 菜。","Sau khi đến Trung Quốc, cô ấy đã mê món ăn Trung Quốc."],["他 去年 没 考 上， 可是 没有 放弃。","Năm ngoái anh ấy thi không đỗ, nhưng không bỏ cuộc."]]}],"dialog":[["A","昨天的网球比赛怎么样？赢了吗？","Trận quần vợt hôm qua thế nào? Thắng không?"],["B","别提了。我练了半年，结果第一场就输了。","Đừng nhắc nữa. Mình tập nửa năm, kết quả là thua ngay trận đầu."],["A","难道你想放弃吗？","Chẳng lẽ cậu định bỏ cuộc sao?"],["B","当时真想放弃，可是教练说，失败也是一种经历。","Lúc đó thật sự muốn bỏ, nhưng huấn luyện viên nói thất bại cũng là một trải nghiệm."],["A","他说得很正确。比赛的过程比结果更重要。","Ông ấy nói rất đúng. Quá trình thi đấu quan trọng hơn kết quả."],["B","是啊，我得好好儿总结一下，至少要知道自己哪儿做得不好。","Đúng thế, mình phải tổng kết kỹ, ít nhất cũng phải biết mình làm chưa tốt ở đâu."],["A","只要坚持下去，你一定能赢。","Chỉ cần kiên trì tiếp, cậu nhất định sẽ thắng."],["B","谢谢！下个月还有一场国际比赛，我想勇敢地试试。","Cảm ơn! Tháng sau còn một giải quốc tế, mình muốn dũng cảm thử xem."]],"radicals":["面","首"],"write":["汗","取"],"hz":{"old":["餐","父母","奖"],"prov":["",""]}},
{"n":10,"zh":"幸福的标准","vi":"Thước đo của hạnh phúc","topic":"Hạnh phúc và nghề nghiệp","words":[["比如","bǐrú","tỷ như","ví dụ như, chẳng hạn"],["不过","búguò","bất quá","nhưng mà, có điều"],["答案","dá'àn","đáp án","đáp án, câu trả lời"],["等","děng","đẳng","vân vân"],["低","dī","đê","thấp"],["发展","fāzhǎn","phát triển","phát triển"],["翻译","fānyì","phiên dịch","phiên dịch; người phiên dịch"],["方向","fāngxiàng","phương hướng","phương hướng, hướng đi"],["富","fù","phú","giàu"],["关键","guānjiàn","quan kiện","mấu chốt, then chốt"],["建议","jiànyì","kiến nghị","đề nghị, lời khuyên"],["将来","jiānglái","tương lai","tương lai, sau này"],["经济","jīngjì","kinh tế","kinh tế"],["空儿","kòngr","không nhi","thời gian rảnh"],["困","kùn","khốn","buồn ngủ"],["拉","lā","lạp","kéo, lôi, dắt"],["礼拜天","lǐbàitiān","lễ bái thiên","chủ nhật"],["母亲","mǔqīn","mẫu thân","mẹ"],["穷","qióng","cùng","nghèo"],["确实","quèshí","xác thực","quả thực, đúng là"],["硕士","shuòshì","thạc sĩ","thạc sĩ"],["糖","táng","đường","kẹo; đường"],["躺","tǎng","thảng","nằm"],["条件","tiáojiàn","điều kiện","điều kiện"],["橡皮","xiàngpí","tượng bì","cục tẩy, gôm"],["兴奋","xīngfèn","hưng phấn","phấn khởi, hào hứng"],["永远","yǒngyuǎn","vĩnh viễn","mãi mãi, vĩnh viễn"],["优秀","yōuxiù","ưu tú","xuất sắc, ưu tú"],["由于","yóuyú","do vu","do, bởi vì"],["职业","zhíyè","chức nghiệp","nghề nghiệp"]],"grammar":[{"t":"Liên từ 不过 (nhưng mà, có điều)","f":"Vế 1，不过 + vế 2 (bổ sung / trái ý)","e":"不过 = “nhưng mà, có điều”, nối vế sau để bổ sung một ý ngược lại hoặc một lưu ý. Giọng nhẹ nhàng hơn 但是, hay dùng trong khẩu ngữ. 不过 đứng đầu vế sau, không đi chung với 但是.","ex":[["这 个 工作 条件 很 好， 不过 离 家 有点儿 远。","Công việc này điều kiện rất tốt, có điều hơi xa nhà."],["钱 很 重要， 不过 不 是 最 关键 的。","Tiền rất quan trọng, nhưng không phải là điều mấu chốt nhất."],["他 的 中文 很 好， 不过 还 不 能 当 翻译。","Tiếng Trung của anh ấy rất tốt, nhưng vẫn chưa thể làm phiên dịch."]]},{"t":"Phó từ 确实 (quả thực, đúng là)","f":"S + 确实 + V / A","e":"确实 khẳng định điều gì đó là đúng sự thật, thường dùng khi đồng ý với người khác: “quả thực, đúng là”. Là phó từ nên đứng sau chủ ngữ, trước động từ/tính từ; không đặt cuối câu như “…thật”.","ex":[["你 说 得 确实 有 道理。","Bạn nói quả thực có lý."],["她 确实 很 优秀， 大家 都 很 喜欢 她。","Cô ấy đúng là rất xuất sắc, ai cũng quý cô ấy."],["这 几 年 这里 的 经济 确实 发展 得 很 快。","Mấy năm nay kinh tế ở đây quả thực phát triển rất nhanh."]]},{"t":"Cấu trúc 在……看来 (theo… thì)","f":"在 + người + 看来，+ quan điểm","e":"在我看来 = “theo tôi thì, với tôi mà nói”, dùng để nêu quan điểm của ai đó. Giữa 在 và 看来 là người, không thêm 的 (在我的看来 ✗), và không thêm 认为 phía sau vì 看来 đã có nghĩa “cho rằng”.","ex":[["在 我 看来， 幸福 的 关键 是 心情 好。","Theo tôi, mấu chốt của hạnh phúc là tâm trạng vui vẻ."],["在 父母 看来， 孩子 永远 是 孩子。","Trong mắt cha mẹ, con cái mãi mãi là con cái."],["在 很 多 人 看来， 富 的 人 才 幸福。","Nhiều người cho rằng người giàu mới hạnh phúc."]]},{"t":"Liên từ 由于 (do, bởi vì)","f":"由于 + nguyên nhân，(因此 / 所以) + kết quả","e":"由于 nêu nguyên nhân, nghĩa giống 因为 nhưng trang trọng hơn, thường dùng trong văn viết. 由于 thường đứng ở vế trước; vế sau có thể dùng 因此 hoặc 所以. Không dùng 由于 ở vế sau như “…，由于…” (muốn vậy thì nói “…，是由于…”).","ex":[["由于 天气 不 好， 礼拜天 的 活动 改 到 下 周 了。","Do thời tiết không tốt, sự kiện chủ nhật đã dời sang tuần sau."],["由于 他 工作 很 优秀， 因此 公司 给 了 他 更 好 的 条件。","Do anh ấy làm việc rất xuất sắc, vì vậy công ty đã cho anh ấy điều kiện tốt hơn."],["由于 昨天 睡 得 太 晚， 我 今天 一直 很 困。","Vì hôm qua ngủ quá muộn nên hôm nay tôi buồn ngủ suốt."]]},{"t":"比如 (ví dụ như)","f":"Ý chung，比如 + A、B (+ 等)","e":"比如 đưa ra ví dụ cụ thể cho ý vừa nói, nghĩa như 例如 nhưng khẩu ngữ hơn; có thể nói 比如说. Cuối danh sách ví dụ hay có 等 (vân vân). Lưu ý 等 đặt sau các ví dụ, không đặt trước.","ex":[["幸福 的 标准 有 很 多， 比如 健康、 家人、 朋友 等。","Thước đo hạnh phúc có nhiều, ví dụ như sức khỏe, gia đình, bạn bè, v.v."],["有 空儿 的 时候 我 喜欢 做 运动， 比如 跑步、 打 网球。","Lúc rảnh tôi thích chơi thể thao, ví dụ như chạy bộ, đánh quần vợt."],["很 多 职业 都 需要 会 外语， 比如 翻译、 导游 等。","Nhiều nghề cần biết ngoại ngữ, chẳng hạn như phiên dịch, hướng dẫn viên du lịch, v.v."]]}],"dialog":[["A","你觉得幸福的标准是什么？","Bạn thấy thước đo của hạnh phúc là gì?"],["B","这个问题没有正确答案。在我看来，有一份自己喜欢的职业就很幸福。","Câu hỏi này không có đáp án đúng. Theo mình, có một nghề mình thích là đã rất hạnh phúc."],["A","不过很多人觉得，钱多才幸福。","Nhưng nhiều người cho rằng nhiều tiền mới hạnh phúc."],["B","钱确实很重要，不过不是最关键的。","Tiền đúng là quan trọng, nhưng không phải là điều mấu chốt nhất."],["A","那什么最关键？","Vậy cái gì là mấu chốt nhất?"],["B","比如身体健康、家人快乐、有空儿做自己喜欢的事等。","Ví dụ như sức khỏe tốt, gia đình vui vẻ, có thời gian rảnh làm việc mình thích, v.v."],["A","由于工作太忙，我已经好几个礼拜天没休息了。","Vì công việc bận quá, mình đã mấy chủ nhật liền không được nghỉ rồi."],["B","那这个礼拜天我们去公园，在草地上躺一躺吧！","Vậy chủ nhật này mình ra công viên, nằm dài trên bãi cỏ một lúc nhé!"]],"radicals":["身","香"],"write":["低","富"]},
{"n":11,"zh":"读书好，读好书，好读书","vi":"Đọc sách có ích, đọc sách hay, ham đọc sách","topic":"Thói quen đọc sách","words":[["表示","biǎoshì","biểu thị","biểu thị, nói lên, có nghĩa là"],["猜","cāi","sai","đoán"],["词语","cíyǔ","từ ngữ","từ ngữ, cách diễn đạt"],["否则","fǒuzé","phủ tắc","nếu không thì"],["复杂","fùzá","phức tạp","phức tạp, rắc rối"],["精彩","jīngcǎi","tinh thái","đặc sắc, hay, tuyệt vời"],["看法","kànfǎ","khán pháp","quan điểm, cách nhìn"],["客厅","kètīng","khách sảnh","phòng khách"],["来得及","láidejí","lai đắc cập","còn kịp, kịp"],["厉害","lìhai","lệ hại","giỏi, cừ; ghê gớm"],["连","lián","liên","ngay cả"],["流利","liúlì","lưu lợi","lưu loát, trôi chảy"],["内容","nèiróng","nội dung","nội dung"],["然而","rán'ér","nhiên nhi","thế nhưng, song"],["顺序","shùnxù","thuận tự","thứ tự, trật tự"],["填空","tián kòng","điền không","điền vào chỗ trống"],["同时","tóngshí","đồng thời","đồng thời, cùng lúc"],["文章","wénzhāng","văn chương","bài văn, bài viết"],["无论","wúlùn","vô luận","bất kể, dù"],["相同","xiāngtóng","tương đồng","giống nhau"],["养成","yǎngchéng","dưỡng thành","hình thành, tập thành (thói quen)"],["页","yè","hiệt","trang (sách)"],["语法","yǔfǎ","ngữ pháp","ngữ pháp"],["阅读","yuèdú","duyệt độc","đọc (sách, báo)"],["杂志","zázhì","tạp chí","tạp chí"],["增加","zēngjiā","tăng gia","tăng thêm"],["之","zhī","chi","của (trợ từ nối định ngữ, văn viết)"],["只好","zhǐhǎo","chỉ hảo","đành phải"],["著名","zhùmíng","trứ danh","nổi tiếng"],["准确","zhǔnquè","chuẩn xác","chính xác"]],"grammar":[{"t":"Cấu trúc 连……也/都……","f":"S + 连 + N/V + 也/都 + V","e":"Nghĩa là “ngay cả… cũng…”, nhấn mạnh một trường hợp cực đoan để suy ra các trường hợp khác. Phần được nhấn mạnh kẹp giữa 连 và 也/都, cả cụm đứng TRƯỚC động từ — người Việt hay đặt tân ngữ ra sau động từ như tiếng Việt.","ex":[["他 连 一 页 书 都 没 看 完。","Ngay cả một trang sách anh ấy cũng chưa đọc xong."],["这么 简单 的 词语， 连 孩子 都 知道。","Từ đơn giản thế này, ngay cả trẻ con cũng biết."],["她 忙 得 连 饭 也 来不及 吃。","Cô ấy bận đến mức ngay cả cơm cũng không kịp ăn."]]},{"t":"Liên từ 否则","f":"Vế 1 (điều nên làm)，否则 + Vế 2 (hậu quả)","e":"否则 = “nếu không thì”. Vế trước nói việc cần làm, vế sau nói hậu quả xấu nếu không làm. Bản thân 否则 đã có nghĩa “nếu không”, nên KHÔNG thêm 如果不 phía trước.","ex":[["你 得 每天 阅读， 否则 汉语 很 难 提高。","Bạn phải đọc mỗi ngày, nếu không thì tiếng Trung khó mà tiến bộ."],["我们 快 走 吧， 否则 就 来不及 了。","Mình đi nhanh thôi, không thì không kịp mất."]]},{"t":"Cấu trúc 无论……都/也……","f":"无论 + từ nghi vấn / A 还是 B，S + 都/也 + V","e":"无论 = “bất kể, dù… thế nào”: điều kiện thay đổi nhưng kết quả không đổi. Sau 无论 PHẢI có từ nghi vấn (多、什么、谁、怎么…) hoặc lựa chọn (A还是B, V不V); không nói 无论下雨.","ex":[["无论 多 忙， 他 每天 都 看 半 个 小时 书。","Dù bận đến đâu, mỗi ngày anh ấy đều đọc sách nửa tiếng."],["无论 是 小说 还是 杂志， 她 都 喜欢 读。","Bất kể là tiểu thuyết hay tạp chí, cô ấy đều thích đọc."],["无论 你 怎么 猜， 也 猜 不 到 结果。","Dù bạn đoán thế nào cũng không đoán ra kết quả."]]},{"t":"Liên từ 然而","f":"Vế 1，然而 + Vế 2 (ý ngược lại)","e":"然而 = “thế nhưng”, giống 但是/可是 nhưng trang trọng hơn, hay dùng trong văn viết. 然而 đứng ĐẦU vế thứ hai, không đứng đầu câu như 虽然.","ex":[["这 篇 文章 的 语法 不 复杂， 然而 内容 很 难 理解。","Ngữ pháp bài này không phức tạp, thế nhưng nội dung rất khó hiểu."],["他 学 了 三 年 汉语， 然而 说 得 还 不 太 流利。","Anh ấy học tiếng Trung ba năm, thế nhưng nói vẫn chưa lưu loát lắm."]]},{"t":"同时: đồng thời","f":"Vế 1，同时 (也/还) + Vế 2 / 在……的同时","e":"同时 nối hai việc cùng xảy ra hoặc bổ sung ý: “đồng thời, cùng lúc, hơn nữa”. Sau 同时 thường có 也/还; 也/还 phải đứng trước động từ, sau chủ ngữ (nếu có).","ex":[["阅读 能 增加 知识， 同时 也 能 让 人 放松。","Đọc sách giúp tăng hiểu biết, đồng thời cũng giúp người ta thư giãn."],["他 在 工作 的 同时， 还 在 学习 英语。","Anh ấy vừa đi làm, đồng thời còn học tiếng Anh."]]}],"dialog":[["A","你客厅里怎么有这么多书和杂志？","Sao phòng khách nhà bạn nhiều sách và tạp chí thế?"],["B","我最近在养成阅读的习惯，每天至少读二十页。","Dạo này mình đang tập thói quen đọc sách, mỗi ngày ít nhất hai mươi trang."],["A","真厉害！我连一本小说都没读完过。","Giỏi thật! Mình còn chưa đọc hết nổi một cuốn tiểu thuyết nào."],["B","无论多忙，你都应该读一点儿，否则很难有自己的看法。","Dù bận mấy bạn cũng nên đọc một chút, không thì khó có quan điểm riêng."],["A","可是有的文章内容太复杂了，我看不懂。","Nhưng có những bài nội dung phức tạp quá, mình đọc không hiểu."],["B","那你可以先读简单的，同时把不认识的词语记下来。","Vậy bạn có thể đọc cái đơn giản trước, đồng thời ghi lại những từ chưa biết."],["A","好主意。你有什么好书介绍给我吗？","Ý hay đấy. Bạn có cuốn nào hay giới thiệu cho mình không?"],["B","这本就很精彩，作者是一位著名的作家，借给你吧。","Cuốn này hay lắm, tác giả là một nhà văn nổi tiếng, cho bạn mượn nhé."]],"radicals":["癶","用"],"write":["连","内"],"hz":{"old":["笔记","减","减轻","兴趣","有效","有限"],"prov":["",""]}},
{"n":12,"zh":"用心发现世界","vi":"Dùng trái tim để khám phá thế giới","topic":"Giao tiếp và thấu hiểu","words":[["保护","bǎohù","bảo hộ","bảo vệ"],["并且","bìngqiě","tịnh thả","và, đồng thời, hơn nữa"],["对于","duìyú","đối vu","đối với"],["规定","guīdìng","quy định","quy định"],["教育","jiàoyù","giáo dục","giáo dục, dạy dỗ"],["节","jié","tiết","tiết (học)"],["节约","jiéyuē","tiết ước","tiết kiệm"],["解释","jiěshì","giải thích","giải thích"],["可惜","kěxī","khả tích","đáng tiếc, tiếc"],["力气","lìqi","lực khí","sức lực, sức"],["全部","quánbù","toàn bộ","toàn bộ, tất cả"],["任务","rènwu","nhiệm vụ","nhiệm vụ"],["商量","shāngliang","thương lượng","bàn bạc, trao đổi"],["勺子","sháozi","chước tử","cái muôi, cái thìa"],["使用","shǐyòng","sử dụng","sử dụng"],["死","sǐ","tử","cứng nhắc, cố định"],["无","wú","vô","không có"],["无法","wú fǎ","vô pháp","không thể, không có cách nào"],["误会","wùhuì","ngộ hội","hiểu lầm; sự hiểu lầm"],["相反","xiāngfǎn","tương phản","trái lại, ngược lại"],["详细","xiángxì","tường tế","chi tiết, tỉ mỉ"],["盐","yán","diêm","muối"],["也许","yěxǔ","dã hứa","có lẽ"],["叶子","yèzi","diệp tử","lá cây"],["意见","yìjiàn","ý kiến","ý kiến"],["引起","yǐnqǐ","dẫn khởi","gây ra, dẫn đến"],["友好","yǒuhǎo","hữu hảo","thân thiện"],["语言","yǔyán","ngữ ngôn","ngôn ngữ"],["直接","zhíjiē","trực tiếp","trực tiếp, thẳng"],["仔细","zǐxì","tử tế","kỹ lưỡng, cẩn thận"],["作用","zuòyòng","tác dụng","tác dụng"],["达到","dádào","đạt đáo","đạt được, đạt tới","*"],["事半功倍","shì bàn gōng bèi","sự bán công bội","làm ít công mà hiệu quả nhiều","*"]],"grammar":[{"t":"Liên từ 并且","f":"V1/A1 + 并且 + V2/A2 / Vế 1，并且 + Vế 2","e":"并且 = “và, hơn nữa, đồng thời”, nối hai động từ, hai tính từ hoặc hai vế câu, vế sau thường bổ sung thêm ý. Khác 和: 和 chủ yếu nối danh từ, KHÔNG dùng 和 để nối hai vế câu hay hai động từ có tân ngữ dài.","ex":[["他 仔细 地 看 了 规定， 并且 写 了 详细 的 意见。","Anh ấy đọc kỹ quy định, và còn viết ý kiến chi tiết."],["这 个 办法 简单 并且 有效。","Cách này đơn giản mà lại hiệu quả."]]},{"t":"Cấu trúc 再……也……","f":"再 + A/V，(S) + 也 + V/A","e":"Nghĩa là “dù… đến mấy cũng…”: điều kiện có tăng lên đến đâu thì kết quả vẫn không đổi. 再 và 也 đều là phó từ, phải đứng trước động từ/tính từ, sau chủ ngữ.","ex":[["工作 再 忙， 也 要 注意 身体。","Công việc dù bận đến mấy cũng phải chú ý sức khỏe."],["你 再 解释， 他 也 不 会 相信 的。","Bạn có giải thích thêm nữa, anh ấy cũng sẽ không tin đâu."],["箱子 太 重 了， 我 用 再 大 的 力气 也 搬 不 动。","Cái thùng nặng quá, mình dùng sức mấy cũng không bê nổi."]]},{"t":"Giới từ 对于","f":"对于 + N，S + V / S + 对于 + N + V","e":"对于 = “đối với”, giới thiệu đối tượng được bàn đến. Có thể đứng đầu câu hoặc sau chủ ngữ. Chỗ nào dùng 对于 được thì thường dùng 对 được, nhưng khi nói thái độ với NGƯỜI (đối xử với ai) chỉ dùng 对: 他对我很友好, không nói 他对于我很友好.","ex":[["对于 这 个 问题， 大家 的 意见 不 一样。","Đối với vấn đề này, ý kiến của mọi người không giống nhau."],["对于 孩子 来说， 父母 的 教育 非常 重要。","Đối với trẻ em, sự dạy dỗ của cha mẹ vô cùng quan trọng."]]},{"t":"Lặp lại lượng từ (名量词重叠)","f":"量词 + 量词 (+ 都) + V/A","e":"Lặp lượng từ (个个、本本、张张、天天、件件…) có nghĩa “mỗi…, cái nào cũng…”. Thường làm chủ ngữ hoặc định ngữ và hay đi với 都 phía sau. Không thêm số đếm phía trước: nói 个个都, không nói 一个个个.","ex":[["我们 班 的 同学 个个 都 很 友好。","Các bạn trong lớp tôi ai cũng rất thân thiện."],["他 家 的 书 本本 都 很 有意思。","Sách nhà anh ấy cuốn nào cũng rất thú vị."],["秋天 到 了， 片片 叶子 都 黄 了。","Mùa thu đến rồi, chiếc lá nào cũng đã vàng."]]},{"t":"相反: trái lại","f":"Vế 1，相反，Vế 2 / A 跟 B 相反","e":"相反 nối hai vế có ý trái ngược, vế sau thường nói điều bất ngờ hơn: “trái lại, ngược lại”. Khi làm liên từ, 相反 thường đứng đầu vế sau, sau nó có dấu phẩy.","ex":[["他 没有 生气， 相反， 他 还 笑 了。","Anh ấy không giận, trái lại còn cười."],["吃 太 多 盐 对 身体 没有 好处， 相反， 会 引起 很 多 问题。","Ăn quá nhiều muối không có lợi cho cơ thể, ngược lại còn gây ra nhiều vấn đề."]]}],"dialog":[["A","新来的那位同事好像不太友好，开会时一句话也不说。","Đồng nghiệp mới hình như không thân thiện lắm, họp cả buổi không nói câu nào."],["B","也许是误会吧。对于新环境，他可能还不太习惯。","Có lẽ là hiểu lầm thôi. Đối với môi trường mới, chắc anh ấy chưa quen lắm."],["A","可是我问他问题，他也不直接回答。","Nhưng mình hỏi gì anh ấy cũng không trả lời thẳng."],["B","他刚来中国，语言还有点儿问题。你再着急也没用，慢慢来。","Anh ấy mới sang Trung Quốc, ngôn ngữ còn hơi khó khăn. Bạn có sốt ruột mấy cũng vô ích, cứ từ từ."],["A","你说得对。那我明天仔细给他解释一下这次的任务。","Bạn nói đúng. Vậy mai mình giải thích kỹ cho anh ấy về nhiệm vụ lần này."],["B","好主意，并且可以问问他有什么意见。","Ý hay đấy, và có thể hỏi xem anh ấy có ý kiến gì."],["A","嗯，我们办公室的人个个都很热情，他很快就会习惯的。","Ừ, người trong văn phòng mình ai cũng nhiệt tình, anh ấy sẽ quen nhanh thôi."]],"radicals":["生","皮"],"write":["反","死"],"hz":{"old":["成","受","数","同样"],"prov":["",""]}},
{"n":13,"zh":"喝着茶看京剧","vi":"Vừa uống trà vừa xem Kinh kịch","topic":"Nghệ thuật và văn hóa truyền thống","words":[["遍","biàn","biến","lần, lượt (làm từ đầu đến cuối)"],["表演","biǎoyǎn","biểu diễn","biểu diễn, trình diễn"],["部分","bùfen","bộ phận","phần, bộ phận"],["餐厅","cāntīng","xan sảnh","nhà hàng, phòng ăn"],["吃惊","chī jīng","ngật kinh","kinh ngạc, giật mình"],["错误","cuòwù","thác ngộ","sai, sai lầm; lỗi"],["大概","dàgài","đại khái","khoảng, có lẽ; đại khái"],["大约","dàyuē","đại ước","khoảng chừng"],["观众","guānzhòng","quan chúng","khán giả"],["厚","hòu","hậu","dày"],["互联网","hùliánwǎng","hỗ liên võng","mạng Internet"],["基础","jīchǔ","cơ sở","nền tảng, cơ sở"],["继续","jìxù","kế tục","tiếp tục"],["进行","jìnxíng","tiến hành","tiến hành"],["京剧","jīngjù","kinh kịch","Kinh kịch"],["开心","kāixīn","khai tâm","vui vẻ"],["苦","kǔ","khổ","đắng; vất vả"],["来自","láizì","lai tự","đến từ"],["偶尔","ǒu'ěr","ngẫu nhĩ","thỉnh thoảng"],["普遍","pǔbiàn","phổ biến","phổ biến"],["稍微","shāowēi","sảo vi","hơi, một chút"],["申请","shēnqǐng","thân thỉnh","xin, đăng ký (xin)"],["省","shěng","tỉnh","tỉnh"],["十分","shífēn","thập phân","rất, vô cùng"],["随着","suízhe","tùy trước","cùng với, theo"],["讨论","tǎolùn","thảo luận","thảo luận, bàn bạc"],["演出","yǎnchū","diễn xuất","buổi biểu diễn; biểu diễn"],["演员","yǎnyuán","diễn viên","diễn viên"],["由","yóu","do","do, bởi"],["有趣","yǒuqù","hữu thú","thú vị"],["正常","zhèngcháng","chính thường","bình thường"],["纸袋","zhǐdài","chỉ đại","túi giấy"]],"grammar":[{"t":"大概: khoảng, có lẽ","f":"大概 + số lượng / 大概 + V (phỏng đoán) / 大概的 + N","e":"大概 là phó từ: đứng trước số lượng (“khoảng”) hoặc trước động từ để phỏng đoán (“có lẽ”). Ngoài ra còn là tính từ/danh từ “đại khái, sơ lược”: 大概的意思. Phó từ 大概 phải đứng trước động từ, không đứng sau.","ex":[["从 这儿 到 剧场 大概 要 二十 分钟。","Từ đây đến nhà hát mất khoảng hai mươi phút."],["他 今天 没 来， 大概 是 生病 了。","Hôm nay anh ấy không đến, có lẽ là bị ốm rồi."],["这 个 京剧 故事 的 大概 意思 我 听懂 了。","Ý đại khái của vở Kinh kịch này tôi nghe hiểu rồi."]]},{"t":"Phó từ 偶尔","f":"S + 偶尔 + V","e":"偶尔 = “thỉnh thoảng, đôi khi”, tần suất thấp hơn 有时候 và 经常. 偶尔 là phó từ nên đứng sau chủ ngữ, trước động từ; không đặt cuối câu như “tôi uống trà thỉnh thoảng”.","ex":[["我 平时 喝 咖啡， 偶尔 也 喝 茶。","Bình thường tôi uống cà phê, thỉnh thoảng cũng uống trà."],["他 很 少 看 京剧， 只是 偶尔 陪 爷爷 去 看 一 次。","Anh ấy ít khi xem Kinh kịch, chỉ thỉnh thoảng đi cùng ông xem một lần."]]},{"t":"Giới từ 由","f":"由 + người + V (phụ trách) / 由 + …… + 组成","e":"由 = “do, bởi”. Dùng để nói ai chịu trách nhiệm làm việc gì: 这件事由我负责; hoặc nói cái gì được tạo thành từ những phần nào: 由……组成. Chú ý: “do ai làm” trong tiếng Việt → 由 + người + động từ, động từ đứng sau người.","ex":[["这 次 演出 由 王 老师 负责。","Buổi biểu diễn lần này do thầy Vương phụ trách."],["这 个 节目 由 三 个 部分 组成。","Tiết mục này gồm ba phần."]]},{"t":"Động từ 进行","f":"进行 + V hai âm tiết (讨论、检查、调查…) / 对 + N + 进行 + V","e":"进行 = “tiến hành”, phía sau phải là một động từ HAI âm tiết mang tính trang trọng, kéo dài (讨论、比赛、检查…). Không nói 进行看、进行说. Muốn nói đối tượng thì dùng 对……进行…….","ex":[["我们 下午 要 对 这 个 问题 进行 讨论。","Chiều nay chúng ta sẽ tiến hành thảo luận vấn đề này."],["比赛 正在 进行， 观众 都 十分 开心。","Trận đấu đang diễn ra, khán giả ai cũng rất vui."]]},{"t":"随着: cùng với, theo","f":"随着 + N (的变化/发展/提高)，S + V","e":"随着 = “cùng với, theo đà”, nêu một sự thay đổi làm điều kiện, vế sau là sự thay đổi kéo theo. Phía sau 随着 là cụm danh từ (互联网的发展、年龄的增加…), cả cụm thường đứng đầu câu; vế sau hay có 越来越.","ex":[["随着 互联网 的 发展， 人们 的 生活 越来越 方便 了。","Cùng với sự phát triển của Internet, cuộc sống của mọi người ngày càng tiện lợi."],["随着 年龄 的 增加， 爷爷 对 京剧 越来越 有 兴趣。","Tuổi càng cao, ông càng hứng thú với Kinh kịch."]]}],"dialog":[["A","周末我请你去看京剧吧，听说这次的演出十分精彩。","Cuối tuần mình mời bạn đi xem Kinh kịch nhé, nghe nói buổi diễn lần này rất đặc sắc."],["B","京剧？我只是偶尔在电视上看过，大部分都听不懂。","Kinh kịch á? Mình chỉ thỉnh thoảng xem trên tivi, phần lớn đều nghe không hiểu."],["A","没关系，演出前会有人进行简单的介绍。","Không sao, trước buổi diễn sẽ có người giới thiệu sơ qua."],["B","那太好了。演出大概多长时间？","Thế thì tốt quá. Buổi diễn kéo dài khoảng bao lâu?"],["A","大约两个小时。我们还可以一边喝茶，一边看。","Khoảng hai tiếng. Mình còn có thể vừa uống trà vừa xem."],["B","真有趣！随着来中国的时间越来越长，我对中国文化也越来越感兴趣了。","Thú vị thật! Càng ở Trung Quốc lâu, mình càng thấy hứng thú với văn hóa Trung Quốc."],["A","那就这么说定了，我先在网上买票。","Vậy chốt thế nhé, mình lên mạng mua vé trước."]],"radicals":["麻","罒"],"write":["由","苦"],"hz":{"old":["春游","袋（子）","凉茶","另"],"prov":["",""]}},
{"n":14,"zh":"保护地球母亲","vi":"Bảo vệ Mẹ Trái Đất","topic":"Bảo vệ môi trường","words":[["抱歉","bàoqiàn","bão khiểm","xin lỗi, áy náy"],["乘坐","chéngzuò","thừa tọa","đi, đáp (xe, tàu, máy bay)"],["出差","chū chāi","xuất sai","đi công tác"],["得意","déyì","đắc ý","đắc ý, hể hả"],["地球","dìqiú","địa cầu","Trái Đất"],["丢","diū","đâu","vứt, ném; làm mất"],["鼓励","gǔlì","cổ lệ","khuyến khích, động viên"],["盒子","hézi","hạp tử","cái hộp"],["既然","jìrán","ký nhiên","đã… thì…"],["减少","jiǎnshǎo","giảm thiểu","giảm bớt"],["拒绝","jùjué","cự tuyệt","từ chối"],["空","kōng","không","trống, rỗng"],["垃圾桶","lājītǒng","lạp ngập dũng","thùng rác"],["毛巾","máojīn","mao cân","khăn mặt, khăn tắm"],["美丽","měilì","mỹ lệ","đẹp"],["目的","mùdì","mục đích","mục đích"],["暖","nuǎn","noãn","ấm, ấm áp"],["扔","rēng","nhưng","ném, vứt bỏ"],["省","shěng","tỉnh","tiết kiệm"],["数量","shùliàng","số lượng","số lượng"],["速度","sùdù","tốc độ","tốc độ"],["塑料袋","sùliàodài","tố liệu đại","túi ni-lông"],["停","tíng","đình","dừng, ngừng"],["卫生间","wèishēngjiān","vệ sinh gian","nhà vệ sinh, phòng tắm"],["温度","wēndù","ôn độ","nhiệt độ"],["污染","wūrǎn","ô nhiễm","ô nhiễm; làm ô nhiễm"],["行","xíng","hành","được, ổn"],["牙膏","yágāo","nha cao","kem đánh răng"],["以","yǐ","dĩ","bằng, lấy, dựa vào"],["于是","yúshì","ư thị","thế là, vì vậy"],["脏","zāng","tạng","bẩn"],["重","zhòng","trọng","nặng"]],"grammar":[{"t":"够: đủ, khá","f":"N + 够 (了) / 够 + A / V + 得 + 够","e":"够 vừa là động từ “đủ” (钱够了、时间不够), vừa là phó từ đứng trước tính từ, nghĩa “khá, đủ…”, nhấn mạnh mức độ: 够大、够热的. Câu phủ định dùng 不够, không dùng 没够 với nghĩa “không đủ”.","ex":[["这 个 盒子 够 大， 能 放 下 所有 的 东西。","Cái hộp này đủ to, để vừa tất cả đồ đạc."],["我们 带 的 水 够 不 够？","Nước chúng ta mang theo có đủ không?"],["今天 的 温度 够 高 的， 别 出去 了。","Hôm nay nhiệt độ khá cao đấy, đừng ra ngoài nữa."]]},{"t":"Giới từ 以","f":"以 + phương thức/tiêu chuẩn + V / 以 + A + 为 + B","e":"以 (văn viết) = “bằng, lấy, theo”: chỉ cách thức hoặc căn cứ của hành động, đứng trước động từ: 以最快的速度跑. Cấu trúc 以 A 为 B = “lấy A làm B”. Người Việt hay bỏ 的 trong 以最快的速度 — nên giữ 的.","ex":[["他 以 最 快 的 速度 跑 到 了 车站。","Anh ấy chạy đến nhà ga với tốc độ nhanh nhất."],["这 次 活动 以 减少 污染 为 目的。","Hoạt động lần này lấy việc giảm ô nhiễm làm mục đích."]]},{"t":"Liên từ 既然","f":"既然 + lý do (đã biết)，(S) + 就/那/也 + kết luận","e":"既然 = “đã… thì…”: vế trước là sự thật cả hai bên đều đã biết, vế sau đưa ra kết luận hoặc lời khuyên, thường có 就. Khác 因为: 因为 nêu nguyên nhân mới, còn 既然 dựa vào điều đã rõ để đề nghị.","ex":[["既然 你 不 舒服， 就 早点儿 回家 休息 吧。","Đã không khỏe thì về nhà nghỉ sớm đi."],["既然 塑料袋 会 污染 环境， 我们 就 少 用 一些。","Đã biết túi ni-lông gây ô nhiễm môi trường thì chúng ta dùng ít đi."]]},{"t":"Liên từ 于是","f":"Vế 1 (sự việc)，于是 + Vế 2 (hành động tiếp theo)","e":"于是 = “thế là, vì vậy”, nối hai sự việc ĐÃ xảy ra, việc sau do việc trước dẫn tới. Chỉ dùng kể chuyện đã xảy ra, không dùng cho lời khuyên hay mệnh lệnh (không nói 于是你去吧).","ex":[["外面 下 起 了 大 雨， 于是 我们 决定 不 出去 了。","Bên ngoài đổ mưa to, thế là chúng tôi quyết định không ra ngoài nữa."],["他 发现 垃圾桶 满 了， 于是 把 垃圾 拿 下 楼 了。","Anh ấy thấy thùng rác đầy, thế là mang rác xuống tầng."]]},{"t":"Trợ từ 什么的","f":"A、B (、C) + 什么的","e":"什么的 đặt sau một hoặc vài sự vật liệt kê, nghĩa là “vân vân, các thứ”. Dùng trong khẩu ngữ, đứng cuối danh sách; không đứng trước danh sách.","ex":[["我 带 了 毛巾、 牙膏、 牙刷 什么的。","Tôi mang khăn mặt, kem đánh răng, bàn chải đánh răng các thứ."],["周末 我 喜欢 看 书、 跑步 什么的。","Cuối tuần tôi thích đọc sách, chạy bộ, vân vân."]]}],"dialog":[["A","出差你怎么带这么多东西？毛巾、牙膏什么的，酒店都有。","Đi công tác sao bạn mang nhiều đồ thế? Khăn mặt, kem đánh răng các thứ khách sạn đều có mà."],["B","酒店的东西大部分都是用一次就扔了，太浪费了。","Đồ ở khách sạn phần lớn dùng một lần là vứt, phí quá."],["A","原来你是为了保护环境啊。","Hóa ra bạn làm vậy là để bảo vệ môi trường."],["B","对，我想减少一点儿垃圾，地球已经被污染得够严重了。","Đúng, mình muốn giảm bớt rác một chút, Trái Đất đã bị ô nhiễm nghiêm trọng lắm rồi."],["A","既然这样，我下次出差也自己带吧。","Đã vậy thì lần sau đi công tác mình cũng tự mang theo."],["B","好啊！东西不重，又省钱又环保。","Hay đấy! Đồ không nặng, vừa tiết kiệm tiền vừa bảo vệ môi trường."]],"radicals":["鼓","鹿"],"write":["丢","扔"],"hz":{"old":["关注","环保","垃圾","暖","牙刷"],"prov":["",""]}},
{"n":15,"zh":"教育孩子的艺术","vi":"Nghệ thuật dạy con","topic":"Gia đình và nuôi dạy con","words":[["棒","bàng","bổng","giỏi, cừ, tuyệt"],["笨","bèn","bổn","ngốc, đần"],["表扬","biǎoyáng","biểu dương","khen ngợi, biểu dương"],["厕所","cèsuǒ","xí sở","nhà vệ sinh"],["粗心","cūxīn","thô tâm","cẩu thả, bất cẩn"],["打针","dǎ zhēn","đả châm","tiêm, chích"],["儿童","értóng","nhi đồng","trẻ em, nhi đồng"],["父亲","fùqīn","phụ thân","cha, bố"],["赶","gǎn","cản","vội, đuổi kịp"],["故意","gùyì","cố ý","cố ý, cố tình"],["管理","guǎnlǐ","quản lý","quản lý"],["害羞","hàixiū","hại tu","xấu hổ, ngại ngùng"],["寒假","hánjià","hàn giả","kỳ nghỉ đông"],["合适","héshì","hợp thích","phù hợp, vừa"],["护士","hùshi","hộ sĩ","y tá"],["怀疑","huáiyí","hoài nghi","nghi ngờ"],["假","jiǎ","giả","giả, không thật"],["骄傲","jiāo'ào","kiêu ngạo","kiêu ngạo; tự hào"],["懒","lǎn","lãn","lười"],["弄","nòng","lộng","làm (cho), khiến"],["批评","pīpíng","phê bình","phê bình, chê trách"],["骗","piàn","phiến","lừa, lừa gạt"],["千万","qiānwàn","thiên vạn","nhất định, nhất thiết (dặn dò)"],["敲","qiāo","xao","gõ"],["孙子","sūnzi","tôn tử","cháu nội (trai)"],["弹钢琴","tán gāngqín","đàn cương cầm","chơi đàn piano"],["响","xiǎng","hưởng","kêu, reo, vang lên"],["醒","xǐng","tỉnh","tỉnh dậy, thức dậy"],["整理","zhěnglǐ","chỉnh lý","sắp xếp, dọn dẹp"],["左右","zuǒyòu","tả hữu","khoảng, chừng"],["闹钟","nàozhōng","náo chung","đồng hồ báo thức","*"]],"grammar":[{"t":"想起来: nhớ ra","f":"S + 想起来 + O / S + 想不起来 / 想起 + O + 来","e":"起来 sau 想 có nghĩa mở rộng: điều đã biết nay “hiện lại” trong đầu — “nhớ ra”. Tân ngữ có thể đặt sau 想起来 hoặc chen giữa 想起 và 来. Đừng nhầm với 想出来 = “nghĩ ra” (ý tưởng mới, trước đó chưa có).","ex":[["我 想 起来 了， 他 叫 张东。","Tôi nhớ ra rồi, anh ấy tên là Trương Đông."],["钥匙 放 在 哪儿 了？ 我 怎么 也 想 不 起来。","Chìa khóa để đâu rồi nhỉ? Tôi nghĩ mãi không nhớ ra."],["看到 这 张 照片， 我 想起 小时候 的 事情 来 了。","Nhìn tấm ảnh này, tôi nhớ lại chuyện hồi nhỏ."]]},{"t":"Động từ 弄","f":"弄 + bổ ngữ kết quả (坏/脏/清楚/好…) / 把 + O + 弄 + kết quả","e":"弄 là động từ “làm” rất chung, thay cho một động từ cụ thể khó nói hoặc không cần nói rõ. Thường đi kèm bổ ngữ kết quả: 弄坏 (làm hỏng), 弄脏 (làm bẩn), 弄清楚 (làm rõ). Hay dùng trong câu chữ 把.","ex":[["孩子 把 新 衣服 弄 脏 了。","Đứa bé làm bẩn bộ quần áo mới rồi."],["这 个 问题 我 还 没 弄 清楚。","Vấn đề này tôi vẫn chưa làm rõ."]]},{"t":"Phó từ 千万","f":"千万 + 要/别/不要 + V","e":"千万 dùng để dặn dò, khuyên nhủ người khác một cách khẩn thiết: “nhất định phải / tuyệt đối đừng”. Chỉ dùng trong câu khuyên, câu cầu khiến; không dùng để nói về việc chắc chắn của bản thân (không nói 我明天千万来, phải nói 我明天一定来).","ex":[["过 马路 的 时候 千万 要 小心。","Khi qua đường nhất định phải cẩn thận."],["你 千万 别 骗 孩子， 他们 都 会 记 住 的。","Anh tuyệt đối đừng lừa trẻ con, chúng đều sẽ nhớ đấy."]]},{"t":"来 chỉ số ước lượng","f":"Số tròn (十/二十/一百…) + 来 + lượng từ + N","e":"来 đặt sau số tròn chục, trăm… để chỉ số xấp xỉ, thường hơi nhiều hơn một chút: 十来个 ≈ khoảng mười mấy cái. 来 đứng GIỮA số và lượng từ. Không dùng với số lẻ như 五来个.","ex":[["教室 里 有 二十 来 个 儿童。","Trong lớp có khoảng hai mươi đứa trẻ."],["他 看 起来 三十 来 岁。","Anh ấy trông chừng ba mươi tuổi."]]},{"t":"左右: khoảng, chừng","f":"Số lượng / thời gian + 左右","e":"左右 đặt SAU số lượng hoặc thời điểm để chỉ con số xấp xỉ: 十点左右、两百块左右. Tiếng Việt nói “khoảng” ở phía trước, nên người Việt hay đặt sai thành 左右十点.","ex":[["我 每天 晚上 十一 点 左右 睡觉。","Tối nào tôi cũng đi ngủ khoảng mười một giờ."],["这 台 钢琴 用 了 二十 年 左右 了。","Cây đàn piano này đã dùng được khoảng hai mươi năm rồi."]]}],"dialog":[["A","你儿子最近怎么样？听说他钢琴弹得很棒。","Con trai chị dạo này thế nào? Nghe nói cháu chơi piano giỏi lắm."],["B","是啊，老师常常表扬他。可是他有点儿骄傲了，每天练习不到半个小时。","Ừ, cô giáo hay khen cháu. Nhưng cháu hơi kiêu rồi, mỗi ngày luyện chưa được nửa tiếng."],["A","孩子骄傲的时候，千万别只批评他。","Khi con kiêu ngạo, chị tuyệt đối đừng chỉ phê bình cháu."],["B","那应该怎么办呢？","Thế thì nên làm thế nào?"],["A","可以给他找一个合适的目标，比如寒假参加一次比赛。","Có thể tìm cho cháu một mục tiêu phù hợp, ví dụ kỳ nghỉ đông tham gia một cuộc thi."],["B","好主意，这样他就不会那么懒了。","Ý hay đấy, như vậy cháu sẽ không lười như thế nữa."],["A","教育孩子是一门艺术，得慢慢来。","Dạy con là cả một nghệ thuật, phải từ từ."]],"radicals":["黄","矛"],"write":["弄","笨"],"hz":{"old":["父母"],"prov":["",""]}},
{"n":16,"zh":"生活可以更美好。","vi":"Cuộc sống có thể tốt đẹp hơn","topic":"Thái độ sống và ứng xử","words":[["报名","bào míng","báo danh","đăng ký, ghi danh"],["表格","biǎogé","biểu cách","mẫu đơn, bảng biểu"],["博士","bóshì","bác sĩ","tiến sĩ"],["参观","cānguān","tham quan","tham quan, đi thăm"],["传真","chuánzhēn","truyền chân","fax; gửi fax"],["导游","dǎoyóu","đạo du","hướng dẫn viên du lịch"],["到底","dàodǐ","đáo để","rốt cuộc (nhấn mạnh trong câu hỏi)"],["敢","gǎn","cảm","dám"],["挂","guà","quải","treo, móc"],["号码","hàomǎ","hiệu mã","số (điện thoại, phòng…)"],["激动","jīdòng","kích động","xúc động, phấn khích"],["记者","jìzhě","ký giả","phóng viên, nhà báo"],["郊区","jiāoqū","giao khu","vùng ngoại ô"],["恐怕","kǒngpà","khủng phạ","e rằng, sợ là"],["冷静","lěngjìng","lãnh tĩnh","bình tĩnh, điềm tĩnh"],["礼貌","lǐmào","lễ mạo","lễ phép, lịch sự"],["马虎","mǎhu","mã hổ","cẩu thả, qua loa"],["签证","qiānzhèng","thiêm chứng","thị thực, visa"],["失望","shīwàng","thất vọng","thất vọng"],["输","shū","thâu","thua"],["同情","tóngqíng","đồng tình","thông cảm, cảm thông"],["推","tuī","thôi","đẩy; lùi lại (thời gian)"],["小伙子","xiǎohuǒzi","tiểu khỏa tử","chàng trai, cậu thanh niên"],["呀","ya","nha","trợ từ cuối câu (biến âm của 啊)"],["预习","yùxí","dự tập","xem bài trước, chuẩn bị bài"],["原谅","yuánliàng","nguyên lượng","tha thứ"],["重点","zhòngdiǎn","trọng điểm","trọng điểm, trọng tâm"],["重视","zhòngshì","trọng thị","xem trọng, chú trọng"],["自信","zìxìn","tự tín","tự tin"],["尊重","zūnzhòng","tôn trọng","tôn trọng"],["代表","dàibiǎo","đại biểu","đại diện, thay mặt","*"]],"grammar":[{"t":"Phó từ 可 nhấn mạnh ngữ khí","f":"可 + tính từ / động từ (+ 了) ; 可别 + V","e":"Trong khẩu ngữ, 可 đứng trước tính từ/động từ để nhấn mạnh cảm xúc: “thật là…, …lắm đấy”, cuối câu hay có 了. 可别 + V = “đừng có mà…”. Người Việt hay nhầm 可 này với 可以 (có thể) — hai từ khác hẳn nhau.","ex":[["这 次 考试 可 重要 了， 你 可 别 马虎。","Kỳ thi lần này quan trọng lắm đấy, cậu đừng có mà qua loa."],["听说 你 拿到 签证 了， 我们 可 为 你 高兴 了！","Nghe nói cậu có visa rồi, bọn mình mừng cho cậu lắm!"],["他 可 不 是 一 个 马虎 的 人。","Anh ấy đâu phải là người cẩu thả."]]},{"t":"Phó từ 恐怕","f":"恐怕 + câu / S + 恐怕 + V","e":"恐怕 nghĩa là “e rằng, sợ là”, dùng để phỏng đoán, thường là chuyện không như ý, giọng hơi lo lắng. Có thể đứng đầu câu hoặc sau chủ ngữ. Không dùng 恐怕 với nghĩa “sợ cái gì” — nghĩa đó phải dùng 怕 / 害怕.","ex":[["天 这么 晚 了， 恐怕 他 不 会 来 了。","Muộn thế này rồi, e là anh ấy không đến nữa."],["这 张 表格 太 复杂， 今天 恐怕 填 不 完。","Mẫu đơn này phức tạp quá, e rằng hôm nay điền không xong."]]},{"t":"Phó từ 到底 trong câu hỏi","f":"S + 到底 + câu hỏi (V不V / từ để hỏi / 还是)","e":"到底 = “rốt cuộc”, dùng khi người nói sốt ruột muốn biết câu trả lời cuối cùng. Câu phải là câu hỏi có từ để hỏi, dạng V不V hoặc 还是; KHÔNG dùng với 吗. Nếu chủ ngữ là từ để hỏi (谁, 哪个) thì 到底 đứng trước chủ ngữ.","ex":[["你 到底 想 不 想 去 郊区 参观？","Rốt cuộc bạn có muốn đi tham quan ngoại ô không?"],["这 张 表格 到底 应该 怎么 填？","Mẫu đơn này rốt cuộc phải điền thế nào?"],["到底 是 谁 把 电话 挂 了？","Rốt cuộc là ai đã cúp máy vậy?"]]},{"t":"Cấu trúc 拿……来说","f":"(就) 拿 + N + 来说， …","e":"Dùng để nêu ví dụ minh họa cho ý vừa nói: “lấy … mà nói, ví dụ như …”. Người hoặc vật làm ví dụ phải nằm giữa 拿 và 来说, sau đó mới nói chi tiết.","ex":[["现在 的 年轻人 越来越 自信 了， 拿 我 弟弟 来说， 他 敢 一个人 去 国外 旅游。","Giới trẻ bây giờ ngày càng tự tin, lấy em trai tôi mà nói, nó dám một mình đi du lịch nước ngoài."],["学习 要 抓 重点， 拿 汉语 来说， 先 要 把 声调 学 好。","Học phải nắm trọng tâm, lấy tiếng Trung mà nói, trước hết phải học tốt thanh điệu."]]},{"t":"Động từ năng nguyện 敢","f":"S + 敢 / 不敢 + V ; 敢不敢 + V？","e":"敢 = “dám”, đứng trước động từ chính. Phủ định là 不敢 (không dám) hoặc 没敢 (đã không dám). Câu hỏi dùng 敢不敢 + V. 我敢说… còn có nghĩa “tôi dám chắc…”.","ex":[["他 第一 次 当 导游， 不 敢 一个人 带 那么 多 客人。","Lần đầu làm hướng dẫn viên, anh ấy không dám dẫn một mình nhiều khách như vậy."],["我 敢 说， 这个 小伙子 以后 一定 能 读 博士。","Tôi dám chắc, cậu thanh niên này sau này nhất định học được tiến sĩ."]]}],"dialog":[["A","你到底报没报名？明天可就是最后一天了！","Rốt cuộc cậu đã đăng ký chưa? Mai là ngày cuối cùng rồi đấy!"],["B","报了，可是表格还没填完，我不敢马虎。","Đăng ký rồi, nhưng mẫu đơn chưa điền xong, mình không dám qua loa."],["A","你做事可真认真。拿上次办签证来说，你一次就办好了。","Cậu làm việc cẩn thận thật đấy. Lấy lần làm visa trước mà nói, cậu làm một lần là xong."],["B","那是因为我知道重点在哪儿。这次恐怕没那么容易。","Đó là vì mình biết trọng tâm ở đâu. Lần này e là không dễ như vậy."],["A","别担心，你要自信一点儿。需要我帮忙吗？","Đừng lo, cậu phải tự tin lên chút. Cần mình giúp không?"],["B","太好了！你帮我看看这几个号码写对了没有。","Tốt quá! Cậu xem giúp mình mấy con số này viết đúng chưa."]],"radicals":["臣","血"],"write":["敢","挂"],"hz":{"old":["美好","填","信"],"prov":["",""]}},
{"n":17,"zh":"人与自然","vi":"Con người và thiên nhiên","topic":"Thiên nhiên và môi trường","words":[["抱","bào","bão","ôm, bế"],["倒","dào","đảo","lại, ngược lại (chỉ sự trái ngược)"],["底","dǐ","để","đáy; cuối (tháng, năm)"],["放暑假","fàng shǔjià","phóng thử giả","nghỉ hè"],["干","gàn","cán","làm"],["公里","gōnglǐ","công lý","ki-lô-mét"],["广播","guǎngbō","quảng bá","phát thanh; chương trình phát thanh"],["海洋","hǎiyáng","hải dương","biển, đại dương"],["活泼","huópō","hoạt bát","hoạt bát, nhanh nhẹn"],["竞争","jìngzhēng","cạnh tranh","cạnh tranh"],["老虎","lǎohǔ","lão hổ","hổ, cọp"],["凉快","liángkuai","lương khoái","mát mẻ"],["毛","máo","mao","lông"],["梦","mèng","mộng","giấc mơ"],["难受","nánshòu","nan thụ","khó chịu (trong người, trong lòng)"],["暖和","nuǎnhuo","noãn hòa","ấm áp"],["排队","pái duì","bài đội","xếp hàng"],["排列","páiliè","bài liệt","sắp xếp (theo thứ tự)"],["热闹","rènao","nhiệt nháo","náo nhiệt, nhộn nhịp"],["仍然","réngrán","nhưng nhiên","vẫn, vẫn còn"],["入口","rùkǒu","nhập khẩu","lối vào, cổng vào"],["森林","sēnlín","sâm lâm","rừng"],["社会","shèhuì","xã hội","xã hội"],["剩","shèng","thặng","còn lại"],["趟","tàng","thảng","chuyến, lượt (lượng từ cho việc đi lại)"],["严格","yángé","nghiêm cách","nghiêm khắc, nghiêm ngặt"],["云","yún","vân","mây"],["照","zhào","chiếu","chụp (ảnh); chiếu, soi"],["美人鱼","Měirényú","mỹ nhân ngư","người cá","*"]],"grammar":[{"t":"Phó từ 倒 (chỉ sự trái ngược)","f":"S + 倒 + V / tính từ","e":"倒 (dào) = “lại, ngược lại”, dùng khi sự việc trái với điều mình nghĩ hoặc trái với lẽ thường. 倒 là phó từ: đứng sau chủ ngữ, trước động từ/tính từ, không đứng đầu câu như “ngược lại” trong tiếng Việt.","ex":[["已经 七月 了， 今天 倒 挺 凉快 的。","Đã tháng bảy rồi, vậy mà hôm nay lại khá mát."],["我 以为 他 会 很 难受， 他 倒 很 冷静。","Tôi tưởng anh ấy sẽ rất khó chịu, ai ngờ anh ấy lại rất bình tĩnh."]]},{"t":"Động từ 干","f":"S + 干 + O (干什么 / 干活儿)","e":"干 (gàn) là “làm”, dùng nhiều trong khẩu ngữ, gần nghĩa với 做: 干什么 (làm gì), 干活儿 (làm việc), 干得好 (làm tốt). Chú ý phân biệt với 干 (gān) nghĩa là “khô” trong 干净, 干杯.","ex":[["放 暑假 了， 你 打算 干 什么？","Nghỉ hè rồi, bạn định làm gì?"],["这个 小伙子 干 活儿 又 快 又 好。","Cậu thanh niên này làm việc vừa nhanh vừa tốt."]]},{"t":"Lượng từ động lượng 趟","f":"V + (了) + số + 趟 + (nơi chốn)","e":"趟 đếm số chuyến đi đi về về: 去一趟, 来了两趟, 跑了三趟. Chỉ dùng với động từ di chuyển (去, 来, 回, 跑, 走); với hành động khác dùng 次. 了 đứng ngay sau động từ, không đặt sau nơi chốn.","ex":[["周末 我 得 回 一 趟 老家。","Cuối tuần tôi phải về quê một chuyến."],["为了 这 件 事， 他 去 了 三 趟 银行。","Vì chuyện này, anh ấy đã đi ngân hàng ba chuyến."]]},{"t":"Cấu trúc 为了……而……","f":"为了 + mục đích + 而 + hành động","e":"Nghĩa là “vì… mà…”, “để… nên…”, mang sắc thái trang trọng, hay gặp trong văn viết. 为了 nêu mục đích, 而 nối mục đích với hành động phía sau. 而 phải đứng ngay trước động từ, không đứng trước 为了.","ex":[["很 多 人 为了 保护 森林 而 努力 工作。","Rất nhiều người làm việc chăm chỉ để bảo vệ rừng."],["我们 不 能 为了 竞争 而 不 讲 礼貌。","Chúng ta không thể vì cạnh tranh mà không giữ phép lịch sự."]]},{"t":"Phó từ 仍然","f":"S + 仍然 + V / tính từ","e":"仍然 = “vẫn, vẫn còn”, chỉ tình trạng không thay đổi dù hoàn cảnh đã khác; trang trọng hơn 还 / 还是. Thường đi với 虽然…, 但是… . Đứng sau chủ ngữ, trước vị ngữ.","ex":[["虽然 已经 十二月 底 了， 这里 仍然 很 暖和。","Dù đã cuối tháng mười hai, ở đây vẫn rất ấm áp."],["过 了 这么 多 年， 他 仍然 记得 那 个 梦。","Bao nhiêu năm trôi qua, anh ấy vẫn còn nhớ giấc mơ ấy."],["小 狗 病 了， 毛 也 少 了 很 多， 可是 它 仍然 很 活泼。","Chú chó con bị ốm, lông cũng rụng nhiều, nhưng nó vẫn rất hiếu động."]]}],"dialog":[["A","放暑假了，你打算干什么？","Nghỉ hè rồi, cậu định làm gì?"],["B","我想去一趟森林公园，听说离这儿只有三十公里。","Mình muốn đi công viên rừng một chuyến, nghe nói cách đây chỉ ba mươi cây số."],["A","夏天去森林倒是个好主意，那儿一定很凉快。","Mùa hè đi rừng lại là ý hay đấy, ở đó chắc chắn mát lắm."],["B","是啊，城市里太热闹了，我想找个安静的地方休息几天。","Ừ, thành phố ồn ào quá, mình muốn tìm chỗ yên tĩnh nghỉ vài ngày."],["A","那儿有老虎吗？我小时候常常梦到老虎。","Ở đó có hổ không? Hồi nhỏ mình hay mơ thấy hổ lắm."],["B","有，不过管理很严格，游客不能离老虎太近。","Có, nhưng quản lý rất nghiêm, du khách không được đến quá gần hổ."],["A","那你多照几张照片给我看看吧。","Vậy cậu chụp nhiều ảnh cho mình xem nhé."],["B","没问题！","Không thành vấn đề!"]],"radicals":["谷","采"],"write":["云","底"],"hz":{"old":["部","改","海","极了","气温","全"],"prov":["",""]}},
{"n":18,"zh":"科技与世界","vi":"Khoa học công nghệ và thế giới","topic":"Công nghệ trong đời sống","words":[["安全","ānquán","an toàn","an toàn"],["地点","dìdiǎn","địa điểm","địa điểm, nơi"],["地址","dìzhǐ","địa chỉ","địa chỉ"],["付款","fù kuǎn","phó khoản","trả tiền, thanh toán"],["火","huǒ","hỏa","hot, đắt khách, được nhiều người thích"],["技术","jìshù","kỹ thuật","kỹ thuật, công nghệ"],["降落","jiàngluò","giáng lạc","hạ cánh"],["交通","jiāotōng","giao thông","giao thông, thông tin liên lạc"],["接着","jiēzhe","tiếp trước","tiếp theo, ngay sau đó; làm tiếp"],["警察","jǐngchá","cảnh sát","cảnh sát"],["举","jǔ","cử","giơ lên; nêu (ví dụ)"],["矿泉水","kuàngquánshuǐ","khoáng tuyền thủy","nước khoáng"],["迷路","mí lù","mê lộ","lạc đường"],["密码","mìmǎ","mật mã","mật mã"],["秒","miǎo","miểu","giây"],["桥","qiáo","kiều","cầu"],["日记","rìjì","nhật ký","nhật ký"],["世纪","shìjì","thế kỷ","thế kỷ"],["是否","shìfǒu","thị phủ","có … hay không"],["收","shōu","thu","nhận, thu"],["受不了","shòubuliǎo","thụ bất liễu","không chịu nổi"],["网站","wǎngzhàn","võng trạm","trang web"],["危险","wēixiǎn","nguy hiểm","nguy hiểm"],["咸","xián","hàm","mặn"],["信封","xìnfēng","tín phong","phong thư, bì thư"],["信息","xìnxī","tín tức","thông tin, tin nhắn"],["邮局","yóujú","bưu cục","bưu điện"],["允许","yǔnxǔ","doãn hứa","cho phép"],["作者","zuòzhě","tác giả","tác giả"],["座","zuò","tọa","tòa, cây (lượng từ cho cầu, núi, nhà cao…)"],["方式","fāngshì","phương thức","phương thức, cách thức","*"],["抓","zhuā","trảo","bắt, túm","*"]],"grammar":[{"t":"Phó từ 是否","f":"S + 是否 + V / tính từ","e":"是否 = “có … hay không”, nghĩa giống 是不是 nhưng trang trọng, hay dùng trong văn viết, thông báo. Đứng trước động từ/tính từ. Câu có 是否 không thêm 吗 ở cuối.","ex":[["我 不 知道 这个 网站 是否 安全。","Tôi không biết trang web này có an toàn hay không."],["飞机 是否 能 按时 降落， 还 要 看 天气。","Máy bay có hạ cánh đúng giờ được hay không còn phải xem thời tiết."]]},{"t":"Cụm 受不了","f":"S + 受不了 ; tính từ + 得 + 受不了","e":"受不了 = “không chịu nổi”, nói về cảm giác khó chịu quá mức (nóng, đói, ồn, tính người…). Có thể đứng một mình hoặc làm bổ ngữ sau tính từ + 得. Dạng khẳng định 受得了 thường dùng trong câu hỏi.","ex":[["这里 的 交通 太 乱 了， 我 真 受不了。","Giao thông ở đây lộn xộn quá, tôi thật không chịu nổi."],["这个 菜 咸 得 让 人 受不了。","Món này mặn đến mức không ai chịu nổi."]]},{"t":"Phó từ 接着","f":"先 + V1， 接着 + V2 ; 接着 + V (làm tiếp)","e":"接着 = “tiếp theo, ngay sau đó”, nối hai hành động liền nhau, hay đi với 先 ở vế trước. 接着 + V còn có nghĩa “làm tiếp việc đang dở”. 接着 đứng trước động từ.","ex":[["他 先 把 地址 发 给 我， 接着 又 打 了 一 个 电话。","Anh ấy gửi địa chỉ cho tôi trước, ngay sau đó lại gọi một cuộc điện thoại."],["休息 十 分钟， 我们 接着 上课。","Nghỉ mười phút, chúng ta học tiếp."]]},{"t":"Liên từ 除此以外","f":"Vế 1， 除此以外， (还 / 也) + vế 2","e":"除此以外 = “ngoài ra”, đứng đầu vế sau để bổ sung thông tin cùng loại. Vế sau thường có 还 hoặc 也.","ex":[["这个 网站 可以 买 机票， 除此以外， 还 能 订 酒店。","Trang web này mua được vé máy bay, ngoài ra còn đặt được khách sạn."],["去 那儿 要 带 护照， 除此以外， 最好 再 带 点儿 现金。","Đến đó phải mang hộ chiếu, ngoài ra tốt nhất nên mang thêm ít tiền mặt."]]},{"t":"Cấu trúc 把……叫作……","f":"S + 把 + A + 叫作 + B","e":"Dùng để nói “gọi A là B”. A là người/vật được gọi tên, đứng sau 把; B là tên gọi, đứng sau 叫作. Nếu không dùng 把 thì nói 叫 + A + B (không có 作).","ex":[["人们 把 这 座 桥 叫作 “新 世纪 桥”。","Mọi người gọi cây cầu này là “cầu Thế Kỷ Mới”."],["年轻人 常常 把 特别 火 的 饭馆 叫作 “网红 店”。","Giới trẻ hay gọi những quán ăn cực đắt khách là “quán hot trên mạng”."]]}],"dialog":[["A","你发现没有？现在用手机就能付款，连钱包都不用带了。","Cậu có để ý không? Bây giờ dùng điện thoại là thanh toán được, ngay cả ví cũng không cần mang."],["B","方便是方便，可是我不知道这样是否安全。","Tiện thì tiện thật, nhưng mình không biết như vậy có an toàn không."],["A","现在技术越来越好了，只要别把密码告诉别人就行。","Giờ công nghệ ngày càng tốt, chỉ cần đừng cho người khác biết mật khẩu là được."],["B","我上次在一个网站上买东西，接着就收到了很多奇怪的信息，真受不了。","Lần trước mình mua đồ trên một trang web, ngay sau đó nhận được rất nhiều tin nhắn lạ, thật không chịu nổi."],["A","所以要选大一点儿的网站。除此以外，也别随便打开陌生人发来的东西。","Cho nên phải chọn trang web lớn một chút. Ngoài ra, cũng đừng tùy tiện mở những thứ người lạ gửi tới."],["B","好，我记住了。","Được, mình nhớ rồi."]],"radicals":["至","而"],"write":["收","桥"],"hz":{"old":["科技","例子","奇特","增","增长"],"prov":["",""]}},
{"n":19,"zh":"生活的味道","vi":"Hương vị cuộc sống","topic":"Sinh hoạt hằng ngày","words":[["包子","bāozi","bao tử","bánh bao"],["场","chǎng","trường","trận, buổi (lượng từ cho thi đấu, biểu diễn…)"],["出生","chūshēng","xuất sinh","sinh ra, ra đời"],["厨房","chúfáng","trù phòng","nhà bếp"],["打印","dǎyìn","đả ấn","in (bằng máy in)"],["打招呼","dǎ zhāohu","đả chiêu hô","chào hỏi"],["戴","dài","đới","đeo, đội (kính, mũ…)"],["刀","dāo","đao","con dao"],["道歉","dào qiàn","đạo khiểm","xin lỗi"],["房东","fángdōng","phòng đông","chủ nhà (nhà cho thuê)"],["复印","fùyìn","phục ấn","photocopy, sao chụp"],["胳膊","gēbo","các bác","cánh tay"],["功夫","gōngfu","công phu","võ thuật, kung fu; công sức, thời gian"],["国籍","guójí","quốc tịch","quốc tịch"],["饺子","jiǎozi","giảo tử","sủi cảo, bánh chẻo"],["禁止","jìnzhǐ","cấm chỉ","cấm"],["理发","lǐ fà","lý phát","cắt tóc"],["零钱","língqián","linh tiền","tiền lẻ"],["乒乓球","pīngpāngqiú","binh bàng cầu","bóng bàn"],["破","pò","phá","rách, thủng, vỡ"],["抬","tái","đài","nâng lên, ngẩng lên"],["脱","tuō","thoát","cởi (quần áo, giày)"],["性别","xìngbié","tính biệt","giới tính"],["学期","xuéqī","học kỳ","học kỳ"],["眼镜","yǎnjìng","nhãn kính","mắt kính"],["羽毛球","yǔmáoqiú","vũ mao cầu","cầu lông"],["占线","zhànxiàn","chiếm tuyến","(điện thoại) máy bận"],["转","zhuǎn","chuyển","quay, xoay; chuyển"],["租","zū","tô","thuê, cho thuê"],["座位","zuòwèi","tọa vị","chỗ ngồi"],["吵","chǎo","sảo","ồn ào; cãi nhau","*"],["舞蹈","wǔdǎo","vũ đạo","múa, điệu múa","*"]],"grammar":[{"t":"Đại từ nghi vấn dùng để phiếm chỉ (任指)","f":"谁 / 什么 / 哪儿 / 怎么 + 都 / 也 + V ; 什么……就……什么","e":"Khi đi với 都 / 也, từ để hỏi không còn là câu hỏi mà có nghĩa “ai cũng, gì cũng, đâu cũng…”. Từ để hỏi + 都 / 也 phải đứng TRƯỚC động từ (tiếng Việt lại nói “không muốn ăn gì cả”). Mẫu “V + 什么 + 就 + V + 什么” nghĩa là “thích gì thì làm nấy”.","ex":[["他 太 累 了， 什么 都 不 想 吃。","Anh ấy mệt quá, chẳng muốn ăn gì cả."],["厨房 里 的 刀 不 见 了， 哪儿 都 找 不 到。","Con dao trong bếp biến mất rồi, tìm đâu cũng không thấy."],["你 想 吃 什么 就 点 什么， 今天 我 请 客。","Bạn muốn ăn gì thì gọi nấy, hôm nay mình mời."]]},{"t":"Bổ ngữ xu hướng 上 (nghĩa mở rộng)","f":"V + 上 (+ O)","e":"上 sau động từ có thể chỉ: đạt được mục tiêu (考上大学), bắt đầu một trạng thái và kéo dài (爱上, 喜欢上), hoặc khép lại / gắn vào (关上门, 戴上眼镜, 穿上). 上 dính liền với động từ, 了 đặt sau 上.","ex":[["他 考 上 了 北京 的 大学， 全家 都 很 高兴。","Cậu ấy đỗ đại học ở Bắc Kinh, cả nhà đều rất vui."],["来 中国 以后， 我 很 快 就 爱 上 了 饺子。","Sau khi đến Trung Quốc, tôi nhanh chóng mê món sủi cảo."],["爷爷 戴 上 眼镜， 认真 地 看 报纸。","Ông nội đeo kính vào, chăm chú đọc báo."]]},{"t":"Bổ ngữ xu hướng 出来 (nghĩa mở rộng)","f":"V + 出来 ; V + 不 + 出来","e":"出来 sau động từ có thể chỉ việc nhận ra, phân biệt được (看出来, 听出来, 认出来) hoặc làm ra cái trước đó chưa có (想出来, 打印出来). Dạng phủ định khả năng: V + 不 + 出来 (看不出来 = nhìn không ra).","ex":[["你 一 说话， 我 就 听 出来 是 你 了。","Bạn vừa nói là mình nghe ra ngay là bạn rồi."],["这个 好 办法 是 谁 想 出来 的？","Cách hay này là ai nghĩ ra vậy?"],["他 戴 了 眼镜， 我 差点儿 没 认 出来。","Anh ấy đeo kính, suýt nữa tôi không nhận ra."]]},{"t":"Cụm từ 总的来说","f":"总的来说， + kết luận","e":"总的来说 = “nói chung, tóm lại”, dùng để tổng kết sau khi đã nói các chi tiết (có thể có mặt tốt, mặt chưa tốt). Đặt ở đầu câu hoặc đầu vế sau.","ex":[["这个 房子 有点儿 小， 但是 总的来说 还 不错。","Căn nhà này hơi nhỏ, nhưng nói chung vẫn khá ổn."],["总的来说， 这个 学期 你 进步 了 很 多。","Nói chung, học kỳ này em tiến bộ rất nhiều."]]},{"t":"Động từ 在于","f":"A + 在于 + B","e":"在于 = “nằm ở, là ở”, chỉ ra điểm then chốt, nguyên nhân hoặc bản chất của sự việc A. Sau 在于 là danh từ, cụm động từ hoặc câu. Không thêm 是 sau 在于.","ex":[["学好 功夫 的 关键 在于 每天 练习。","Bí quyết học giỏi võ là ở việc luyện tập mỗi ngày."],["生活 的 味道 不 在于 吃 得 多 好， 而 在于 和 谁 一起 吃。","Hương vị cuộc sống không nằm ở ăn ngon đến đâu, mà ở chỗ ăn cùng ai."]]}],"dialog":[["A","你新租的房子怎么样？","Căn nhà cậu mới thuê thế nào?"],["B","总的来说还不错，房东人很好，厨房也很大。","Nói chung là khá ổn, chủ nhà rất tốt, bếp cũng rộng."],["A","那太好了。你平时自己做饭吗？","Thế thì tốt quá. Bình thường cậu tự nấu ăn à?"],["B","做啊，我最近爱上了包饺子，周末你来尝尝吧。","Có chứ, dạo này mình mê gói sủi cảo, cuối tuần cậu qua nếm thử nhé."],["A","好啊！我什么都爱吃。对了，房子离公司远不远？","Được đấy! Món gì mình cũng thích ăn. À, nhà có xa công ty không?"],["B","有点儿远，不过坐地铁一般都有座位，也不用转车。","Hơi xa, nhưng đi tàu điện ngầm thường có chỗ ngồi, cũng không phải chuyển tàu."],["A","那就好。我觉得租房子的关键在于住得舒服。","Vậy thì tốt. Mình thấy thuê nhà quan trọng nhất là ở có thoải mái không."],["B","你说得对，我现在每天都很开心。","Cậu nói đúng, giờ ngày nào mình cũng vui."]],"radicals":["舌","色"],"write":["刀","转"],"hz":{"old":["表","理发店","小区"],"prov":["",""]}},
{"n":20,"zh":"路上的风景","vi":"Phong cảnh dọc đường","topic":"Du lịch và đi đường","words":[["出发","chūfā","xuất phát","xuất phát, khởi hành"],["存","cún","tồn","gửi (tiền, đồ); lưu giữ"],["打扮","dǎban","đả phẫn","ăn diện, trang điểm"],["登机牌","dēngjīpái","đăng cơ bài","thẻ lên máy bay"],["对话","duìhuà","đối thoại","đối thoại, nói chuyện"],["对面","duìmiàn","đối diện","đối diện, phía trước mặt"],["干杯","gān bēi","can bôi","cạn ly"],["高速公路","gāosù gōnglù","cao tốc công lộ","đường cao tốc"],["航班","hángbān","hàng ban","chuyến bay"],["合格","hégé","hợp cách","đạt tiêu chuẩn, đạt yêu cầu"],["加油站","jiāyóuzhàn","gia du trạm","cây xăng, trạm xăng"],["究竟","jiūjìng","cứu cánh","rốt cuộc (nhấn mạnh trong câu hỏi)"],["烤鸭","kǎoyā","khảo áp","vịt quay"],["棵","kē","khỏa","cây (lượng từ cho cây cối)"],["可怜","kělián","khả liên","đáng thương, tội nghiệp"],["辣","là","lạt","cay"],["旅行","lǚxíng","lữ hành","du lịch, đi chơi xa"],["民族","mínzú","dân tộc","dân tộc"],["普通话","pǔtōnghuà","phổ thông thoại","tiếng phổ thông (tiếng Trung chuẩn)"],["收拾","shōushi","thu thập","dọn dẹp, thu xếp"],["首都","shǒudū","thủ đô","thủ đô"],["酸","suān","toan","chua"],["汤","tāng","thang","canh, súp"],["推迟","tuīchí","thôi trì","hoãn lại"],["香","xiāng","hương","thơm"],["小吃","xiǎochī","tiểu ngật","món ăn vặt"],["笑话","xiàohua","tiếu thoại","truyện cười; chê cười"],["钥匙","yàoshi","thược thi","chìa khóa"],["祝贺","zhùhè","chúc hạ","chúc mừng"],["怪","guài","quái","khá, rất (khẩu ngữ)","*"]],"grammar":[{"t":"Cấu trúc V着V着","f":"V着V着， (就) + việc xảy ra","e":"Lặp lại “V着” hai lần để diễn tả: trong khi một hành động đang kéo dài thì (bất ngờ) xảy ra việc khác, giống tiếng Việt “đang… mãi thì…”. Vế sau thường có 就. Phải lặp cả cụm V着, không nói 听听着.","ex":[["他 听 着 听 着 就 睡 着 了。","Anh ấy nghe một hồi rồi ngủ thiếp đi."],["我们 聊 着 聊 着， 车 已经 开 上 了 高速公路。","Chúng tôi nói chuyện mải mê, xe đã chạy lên đường cao tốc lúc nào không hay."]]},{"t":"Cấu trúc 一……就……","f":"S + 一 + V1， (S2) + 就 + V2","e":"Nghĩa là “vừa… là…” (hai việc nối tiếp ngay) hoặc “hễ… là…” (cứ có điều kiện này là có kết quả kia). 一 và 就 đều đứng sau chủ ngữ, trước động từ; nếu hai vế có hai chủ ngữ khác nhau thì 就 đứng sau chủ ngữ thứ hai.","ex":[["我 一 到 机场 就 给 你 打 电话。","Tôi vừa đến sân bay là gọi cho bạn ngay."],["航班 一 推迟， 大家 就 着急 了。","Chuyến bay vừa bị hoãn là mọi người cuống lên."],["他 一 吃 辣 的 就 出 很 多 汗。","Cứ ăn đồ cay là anh ấy đổ rất nhiều mồ hôi."]]},{"t":"Phó từ 究竟","f":"S + 究竟 + câu hỏi","e":"究竟 = “rốt cuộc”, nghĩa giống 到底 nhưng trang trọng hơn, dùng trong câu hỏi để truy hỏi đáp án cuối cùng. Câu phải có từ để hỏi hoặc dạng V不V / 还是; không dùng với 吗.","ex":[["航班 究竟 推迟 到 几 点？","Chuyến bay rốt cuộc bị hoãn đến mấy giờ?"],["这个 笑话 究竟 哪儿 好笑？ 我 怎么 听 不 懂？","Truyện cười này rốt cuộc buồn cười ở chỗ nào? Sao mình nghe không hiểu?"]]},{"t":"Bổ ngữ xu hướng 起来 (nghĩa mở rộng)","f":"V / A + 起来 ; V + 起 + O + 来","e":"起来 sau động từ/tính từ có thể chỉ: bắt đầu và tiếp diễn (笑起来, 热起来), nhận xét đánh giá (看起来, 吃起来, 听起来), hoặc nhớ ra (想起来). Khi có tân ngữ, tân ngữ chen giữa 起 và 来: 下起雨来, 唱起歌来.","ex":[["大家 一 听 这个 笑话， 都 笑 了 起来。","Mọi người vừa nghe truyện cười này đã cười ồ lên."],["这 道 菜 看 起来 很 辣， 吃 起来 倒 不 太 辣。","Món này trông có vẻ cay lắm, ăn vào lại không cay lắm."],["我 想 起来 了， 钥匙 在 对面 的 桌子 上。","Tôi nhớ ra rồi, chìa khóa ở trên cái bàn đối diện."]]},{"t":"Cấu trúc V + 起","f":"说起 / 提起 / 想起 / 谈起 + O","e":"起 sau một số động từ như 说, 提, 想, 谈 có nghĩa “nhắc đến, nói đến, nhớ đến” một người hay một việc. Thường đứng đầu câu để mở ra chủ đề. 起 dính liền sau động từ, tân ngữ đứng sau 起.","ex":[["说起 北京， 我 第一 个 想到 的 就 是 烤鸭。","Nhắc đến Bắc Kinh, thứ đầu tiên tôi nghĩ đến là vịt quay."],["每次 想起 那 次 旅行， 我 都 觉得 很 开心。","Mỗi lần nhớ lại chuyến đi đó, tôi đều thấy rất vui."]]}],"dialog":[["A","东西都收拾好了吗？我们几点出发？","Đồ đạc thu xếp xong hết chưa? Mình mấy giờ xuất phát?"],["B","早上七点出发，走高速公路，中午就能到。","Bảy giờ sáng xuất phát, đi đường cao tốc, trưa là tới."],["A","太好了！说起那个地方，我最想吃那儿的小吃。","Tuyệt quá! Nhắc đến chỗ đó, mình thèm nhất là đồ ăn vặt ở đấy."],["B","听说那儿的菜又酸又辣，你吃得了吗？","Nghe nói món ăn ở đó vừa chua vừa cay, cậu ăn được không?"],["A","没问题，我一吃辣的就特别开心。","Không vấn đề, mình cứ ăn cay là vui lắm."],["B","那路上我们找个加油站休息一下，顺便买点儿水。","Vậy dọc đường mình tìm một trạm xăng nghỉ chân, tiện mua ít nước."],["A","好！对了，车钥匙你放哪儿了？","Được! À, chìa khóa xe cậu để đâu rồi?"],["B","我想起来了，在门口的桌子上。","Mình nhớ ra rồi, ở trên bàn cạnh cửa."]],"radicals":["行","赤"],"write":["存","汤"],"hz":{"old":["风景","加油"],"prov":["",""]}}];
const RADICALS={"黑":["黑","Hắc","màu đen","黑默墨"],"音":["音","Âm","âm thanh","音意章暗"],"角":["角","Giác","cái sừng; góc","角解触"],"鱼":["鱼","Ngư","con cá","鱼鲜鲸"],"示":["示","Thị","bày ra, chỉ bảo","示票标禁"],"羽":["羽","Vũ","lông chim","羽翻扇翅"],"骨":["骨","Cốt","xương","骨滑骼"],"食":["食","Thực","ăn; thức ăn","食餐飨"],"齿":["齿","Xỉ","răng","齿龄龈"],"革":["革","Cách","da thuộc","革鞋靴"],"隹":["隹","Chuy","chim đuôi ngắn","谁难准售"],"豆":["豆","Đậu","hạt đậu; bát đựng đồ cúng","豆短登逗"],"辛":["辛","Tân","cay; vất vả","辛辣辞"],"鬼":["鬼","Quỷ","ma quỷ","鬼魂魔"],"里":["里","Lý","làng; dặm","里理量野"],"非":["非","Phi","không, sai trái","非啡排悲"],"面":["面","Diện","mặt","面缅腼"],"首":["首","Thủ","đầu","首道馗"],"身":["身","Thân","thân mình","身躺射躲"],"香":["香","Hương","mùi thơm","香馨馥"],"癶":["癶","Bát","gạt ngược lại, hai chân dang ra","登凳癸"],"用":["用","Dụng","dùng","用甬通痛"],"生":["生","Sinh","sống, sinh ra","生星姓胜"],"皮":["皮","Bì","da","皮被破疲"],"麻":["麻","Ma","cây gai","麻嘛摩磨"],"罒":["罒","Võng","cái lưới","罗置罚罢"],"鼓":["鼓","Cổ","cái trống","鼓瞽臌"],"鹿":["鹿","Lộc","con hươu","鹿麓麒麟"],"黄":["黄","Hoàng","màu vàng","黄横簧"],"矛":["矛","Mâu","cây giáo","矛柔茅矜"],"臣":["臣","Thần","bề tôi","臣卧藏"],"血":["血","Huyết","máu","血恤衅"],"谷":["谷","Cốc","thung lũng; lúa gạo","谷容俗浴"],"采":["采","Thái","hái","采彩菜踩"],"至":["至","Chí","đến, tới","至到室屋"],"而":["而","Nhi","mà; râu","而耐需端"],"舌":["舌","Thiệt","lưỡi","舌甜话活"],"色":["色","Sắc","màu sắc","色艳绝"],"行":["行","Hành","đi; hàng lối","行街衡衔"],"赤":["赤","Xích","màu đỏ","赤赫赦"]};
