const w4b_no=(x,y,r,cls,d)=>`<g class="${cls||'wa-pop'}"${d?` style="animation-delay:${d}s"`:''}><circle cx="${x}" cy="${y}" r="${r}" fill="#fff" stroke="#e5383b" stroke-width="${w4b_f(r*.22)}"/><path d="M${x-r*.45},${y-r*.45} L${x+r*.45},${y+r*.45} M${x+r*.45},${y-r*.45} L${x-r*.45},${y+r*.45}" stroke="#e5383b" stroke-width="${w4b_f(r*.22)}" stroke-linecap="round"/></g>`;
const w4b_coin=(x,y,r)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="#ffc93c" stroke="${w4b_I}" stroke-width="1.6"/><circle cx="${x}" cy="${y}" r="${w4b_f(r*.7)}" fill="none" stroke="#e0a21a" stroke-width="1.2"/>`+waTxt(x,w4b_f(y+r*.42),'¥',w4b_f(r*1.1),'#b8860b');
const w4b_clock=(x,y,r,hh,mm,spin)=>{const ha=((hh%12)+mm/60)*30*Math.PI/180,ma=mm*6*Math.PI/180;
  return `<circle cx="${x}" cy="${y}" r="${r}" fill="#fff" stroke="${w4b_I}" stroke-width="2.2"/>${[0,3,6,9].map(k=>{const a=k*Math.PI/6;return `<circle cx="${w4b_f(x+(r-4)*Math.sin(a))}" cy="${w4b_f(y-(r-4)*Math.cos(a))}" r="1.6" fill="${w4b_I}"/>`;}).join('')}`
  +`<path d="M${x},${y} L${w4b_f(x+r*.5*Math.sin(ha))},${w4b_f(y-r*.5*Math.cos(ha))}" stroke="${w4b_I}" stroke-width="3" stroke-linecap="round"/>`
  +`<path d="M${x},${y} L${w4b_f(x+r*.78*Math.sin(ma))},${w4b_f(y-r*.78*Math.cos(ma))}" stroke="#e5383b" stroke-width="2" stroke-linecap="round">${spin?`<animateTransform attributeName="transform" type="rotate" from="0 ${x} ${y}" to="360 ${x} ${y}" dur="${spin}s" repeatCount="indefinite"/>`:''}</path><circle cx="${x}" cy="${y}" r="2.4" fill="${w4b_I}"/>`;};
const w4b_doc=(x,y,w,h,c)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="3" fill="${c||'#fff'}" stroke="${w4b_I}" stroke-width="1.6"/>`+(()=>{let s='';for(let ly=y+9;ly<y+h-5;ly+=7)s+=`<path d="M${x+6},${ly} L${x+w-(ly%14?6:12)},${ly}" stroke="#b9c2cf" stroke-width="2" stroke-linecap="round"/>`;return s;})();
const w4b_bulb=(x,y,cls,d)=>`<g class="${cls||'wa-pulse'}" style="transform-origin:${x}px ${y}px${d?`;animation-delay:${d}s`:''}">${[0,60,120,180,240,300].map(a=>{const c=Math.cos(a*Math.PI/180),s=Math.sin(a*Math.PI/180);return `<path d="M${w4b_f(x+c*15)},${w4b_f(y+s*15)} L${w4b_f(x+c*20)},${w4b_f(y+s*20)}" stroke="#f5a623" stroke-width="2.4" stroke-linecap="round"/>`;}).join('')}<circle cx="${x}" cy="${y}" r="11" fill="#ffe14d" stroke="${w4b_I}" stroke-width="1.8"/><rect x="${x-5}" y="${y+9}" width="10" height="7" rx="2" fill="#9aa5b8" stroke="${w4b_I}" stroke-width="1.4"/></g>`;
