const w4d_cloud=(x,y,s,c)=>`<g transform="translate(${x} ${y}) scale(${s})"><path d="M-22,8 Q-29,8 -28,1 Q-28,-7 -18,-6 Q-16,-16 -4,-14 Q4,-22 14,-14 Q26,-14 24,-2 Q30,0 28,6 Q26,10 20,8Z" fill="${c||'#fff'}" stroke="${w4d_I}" stroke-width="1.8"/></g>`;
const w4d_drop=(x,y,c,cls,d)=>`<path${cls?` class="${cls}" style="transform-origin:${x}px ${y}px;animation-delay:${d||0}s"`:''} d="M${x},${y-6} Q${x-5},${y+2} ${x},${y+5} Q${x+5},${y+2} ${x},${y-6}Z" fill="${c||'#6cc4f0'}" stroke="${w4d_I}" stroke-width="1.2"/>`;
const w4d_ok=(x,y,r,d)=>`<g class="wa-pop" style="animation-delay:${d||0}s"><circle cx="${x}" cy="${y}" r="${r}" fill="#3fb37f" stroke="${w4d_I}" stroke-width="1.6"/><path d="M${x-r*.5},${y} L${x-r*.12},${y+r*.38} L${x+r*.55},${y-r*.38}" fill="none" stroke="#fff" stroke-width="${(r*.28).toFixed(1)}" stroke-linecap="round" stroke-linejoin="round"/></g>`;
