/* HSK4 Bài 9–10 */
const w4e_I=WA_INK;
const w4e_g=(cls,x,y,inner,d)=>`<g class="${cls}" style="transform-origin:${x}px ${y}px${d?`;animation-delay:${d}s`:''}">${inner}</g>`;
const w4e_ok=(x,y,r,cls,d)=>w4e_g(cls||'wa-pop',x,y,`<circle cx="${x}" cy="${y}" r="${r}" fill="#3fb37f" stroke="${w4e_I}" stroke-width="1.8"/><path d="M${x-r*.5},${y} L${x-r*.12},${y+r*.38} L${x+r*.55},${y-r*.35}" fill="none" stroke="#fff" stroke-width="${r*.26}" stroke-linecap="round" stroke-linejoin="round"/>`,d);
const w4e_no=(x,y,r,cls,d)=>w4e_g(cls||'wa-pop',x,y,`<circle cx="${x}" cy="${y}" r="${r}" fill="#fff" stroke="#e5383b" stroke-width="${r*.22}"/><path d="M${x-r*.45},${y-r*.45} L${x+r*.45},${y+r*.45} M${x+r*.45},${y-r*.45} L${x-r*.45},${y+r*.45}" stroke="#e5383b" stroke-width="${r*.22}" stroke-linecap="round"/>`,d);
const w4e_arrow=(x1,y,x2,c)=>`<path d="M${x1},${y} L${x2-8},${y}" stroke="${c||w4e_I}" stroke-width="3.5" stroke-linecap="round"/><path d="M${x2},${y} L${x2-10},${y-7} L${x2-10},${y+7}Z" fill="${c||w4e_I}"/>`;
const w4e_coin=(x,y,r)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="#ffc93c" stroke="${w4e_I}" stroke-width="1.5"/><circle cx="${x}" cy="${y}" r="${r*.62}" fill="none" stroke="#e0a21a" stroke-width="1.2"/>`;
const w4e_cookie=(x,y,r)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="#e3a85f" stroke="${w4e_I}" stroke-width="1.6"/>`+[[-.4,-.3],[.35,-.35],[0,.1],[-.35,.45],[.45,.35]].map(([a,b])=>`<circle cx="${(x+a*r).toFixed(1)}" cy="${(y+b*r).toFixed(1)}" r="${(r*.13).toFixed(1)}" fill="#6b3f2a"/>`).join('');
