/* HSK4 Bài 11–12 */
const w4f_I=WA_INK;
const w4f_ok=(x,y,r,d)=>`<g class="wa-pop" style="animation-delay:${d||0}s"><circle cx="${x}" cy="${y}" r="${r}" fill="#3fb37f" stroke="${w4f_I}" stroke-width="1.6"/><path d="M${x-r*.45},${y} L${x-r*.1},${y+r*.38} L${x+r*.5},${y-r*.35}" fill="none" stroke="#fff" stroke-width="${Math.max(2.4,r*.28).toFixed(1)}" stroke-linecap="round" stroke-linejoin="round"/></g>`;
const w4f_no=(x,y,r,d)=>`<g class="wa-pop" style="animation-delay:${d||0}s"><circle cx="${x}" cy="${y}" r="${r}" fill="#e5383b" stroke="${w4f_I}" stroke-width="1.6"/><path d="M${x-r*.4},${y-r*.4} L${x+r*.4},${y+r*.4} M${x+r*.4},${y-r*.4} L${x-r*.4},${y+r*.4}" stroke="#fff" stroke-width="${Math.max(2.4,r*.28).toFixed(1)}" stroke-linecap="round"/></g>`;
const w4f_arr=(x1,y1,x2,y2,c,cls,d)=>{const a=Math.atan2(y2-y1,x2-x1),p=(k)=>`${(x2-11*Math.cos(a+k)).toFixed(1)},${(y2-11*Math.sin(a+k)).toFixed(1)}`;
  return `<g${cls?` class="${cls}" style="transform-origin:${x1}px ${y1}px;animation-delay:${d||0}s"`:''}><path d="M${x1},${y1} L${x2},${y2}" stroke="${c}" stroke-width="5" stroke-linecap="round"/><path d="M${p(.5)} L${x2},${y2} L${p(-.5)}" fill="none" stroke="${c}" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/></g>`;};
const w4f_lines=(x,y,w,n,g,c)=>{let s='';for(let k=0;k<n;k++)s+=`<path d="M${x},${y+k*g} L${x+(k===n-1?w*.6:w)},${y+k*g}" stroke="${c||'#9aa6b2'}" stroke-width="2.2" stroke-linecap="round"/>`;return s;};
const w4f_book=(x,y,c)=>`<path d="M${x-30},${y+2} L${x-30},${y+34} Q${x-14},${y+31} ${x},${y+37} Q${x+14},${y+31} ${x+30},${y+34} L${x+30},${y+2}Z" fill="${c||'#5a8fd6'}" stroke="${w4f_I}" stroke-width="1.6" stroke-linejoin="round"/><path d="M${x},${y+4} Q${x-13},${y-2} ${x-27},${y} L${x-27},${y+30} Q${x-13},${y+28} ${x},${y+34} Q${x+13},${y+28} ${x+27},${y+30} L${x+27},${y} Q${x+13},${y-2} ${x},${y+4}Z M${x},${y+4} L${x},${y+34}" fill="#fff" stroke="${w4f_I}" stroke-width="1.6" stroke-linejoin="round"/>`;
const w4f_paper=(x,y,w,h,c)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="4" fill="${c||'#fff'}" stroke="${w4f_I}" stroke-width="1.8"/>`;
const w4f_clock=(x,y,r,h,m,cls)=>{const hand=(ang,l,wd)=>{const a=(ang-90)*Math.PI/180;return `<path d="M${x},${y} L${(x+l*Math.cos(a)).toFixed(1)},${(y+l*Math.sin(a)).toFixed(1)}" stroke="${w4f_I}" stroke-width="${wd}" stroke-linecap="round"/>`;};
  return `<g${cls?` class="${cls}" style="transform-origin:${x}px ${y}px"`:''}><circle cx="${x}" cy="${y}" r="${r}" fill="#fff" stroke="${w4f_I}" stroke-width="2"/>${[0,90,180,270].map(a=>{const t=(a-90)*Math.PI/180;return `<circle cx="${(x+(r-4)*Math.cos(t)).toFixed(1)}" cy="${(y+(r-4)*Math.sin(t)).toFixed(1)}" r="1.3" fill="${w4f_I}"/>`;}).join('')}${hand(h,r*.5,3)}${hand(m,r*.75,2)}<circle cx="${x}" cy="${y}" r="2" fill="#e5383b"/></g>`;};
const w4f_bulb=(x,y,cls,d)=>`<g class="${cls||'wa-pop'}" style="transform-origin:${x}px ${y}px;animation-delay:${d||0}s"><circle cx="${x}" cy="${y}" r="11" fill="#ffe066" stroke="${w4f_I}" stroke-width="1.6"/><rect x="${x-5}" y="${y+10}" width="10" height="7" rx="2" fill="#aab" stroke="${w4f_I}" stroke-width="1.4"/><path d="M${x-3},${y+2} L${x},${y-3} L${x+3},${y+2}" fill="none" stroke="#f29e1f" stroke-width="1.6"/>${[-60,0,60].map(a=>{const t=(a-90)*Math.PI/180;return `<path d="M${(x+15*Math.cos(t)).toFixed(1)},${(y+15*Math.sin(t)).toFixed(1)} L${(x+21*Math.cos(t)).toFixed(1)},${(y+21*Math.sin(t)).toFixed(1)}" stroke="#f29e1f" stroke-width="2.4" stroke-linecap="round"/>`;}).join('')}</g>`;
const w4f_think=(x,y,w,h,tx,ty)=>`<ellipse cx="${x}" cy="${y}" rx="${w/2}" ry="${h/2}" fill="#fff" stroke="${w4f_I}" stroke-width="1.8"/><circle cx="${tx}" cy="${ty}" r="3.5" fill="#fff" stroke="${w4f_I}" stroke-width="1.5"/><circle cx="${(tx+(x-tx)*.45).toFixed(1)}" cy="${(ty+(y+h/2-ty)*.45).toFixed(1)}" r="2.2" fill="#fff" stroke="${w4f_I}" stroke-width="1.3"/>`;
const w4f_cloud=(x,y,s,c,cls)=>`<path${cls?` class="${cls}" style="transform-origin:${x}px ${y}px"`:''} d="M${x-22*s},${y+8*s} Q${x-30*s},${y+8*s} ${x-28*s},${y} Q${x-26*s},${y-9*s} ${x-16*s},${y-7*s} Q${x-12*s},${y-19*s} ${x},${y-17*s} Q${x+13*s},${y-18*s} ${x+16*s},${y-7*s} Q${x+28*s},${y-8*s} ${x+28*s},${y+2*s} Q${x+29*s},${y+8*s} ${x+21*s},${y+8*s}Z" fill="${c||'#fff'}" stroke="${w4f_I}" stroke-width="1.8" stroke-linejoin="round"/>`;
const w4f_rain=(xs,y)=>xs.map((x,k)=>`<path class="wa-drip" style="animation-delay:${((k*0.37)%1.6).toFixed(2)}s" d="M${x},${y+(k%3)*10} l-3,7" stroke="#5a8fd6" stroke-width="2.4" stroke-linecap="round"/>`).join('');
const w4f_sun=(x,y,r)=>`<g><g><animateTransform attributeName="transform" type="rotate" from="0 ${x} ${y}" to="360 ${x} ${y}" dur="12s" repeatCount="indefinite"/>${[0,45,90,135,180,225,270,315].map(a=>{const c=Math.cos(a*Math.PI/180),s=Math.sin(a*Math.PI/180);return `<path d="M${(x+c*(r+4)).toFixed(1)},${(y+s*(r+4)).toFixed(1)} L${(x+c*(r+10)).toFixed(1)},${(y+s*(r+10)).toFixed(1)}" stroke="#f5a623" stroke-width="3.5" stroke-linecap="round"/>`;}).join('')}</g><circle cx="${x}" cy="${y}" r="${r}" fill="#ffd166" stroke="${w4f_I}" stroke-width="1.8"/></g>`;
const w4f_card=(x,y,w,h,t,c,sz,cls,d)=>`<g${cls?` class="${cls}" style="transform-origin:${x}px ${y}px;animation-delay:${d||0}s"`:''}><rect x="${x-w/2}" y="${y-h/2}" width="${w}" height="${h}" rx="7" fill="#fff" stroke="${c}" stroke-width="2.2"/>${waTxt(x,y+(sz||16)*.36,t,sz||16,c)}</g>`;
const w4f_mag=(x,y,r,cls)=>`<g${cls?` class="${cls}" style="transform-origin:${x}px ${y}px"`:''}><path d="M${x+r*.7},${y+r*.7} L${x+r*1.6},${y+r*1.6}" stroke="#7a5230" stroke-width="6" stroke-linecap="round"/><circle cx="${x}" cy="${y}" r="${r}" fill="#dff3ff" fill-opacity=".55" stroke="${w4f_I}" stroke-width="3"/><path d="M${x-r*.5},${y-r*.3} Q${x-r*.4},${y-r*.6} ${x-r*.1},${y-r*.65}" fill="none" stroke="#fff" stroke-width="2.5" stroke-linecap="round"/></g>`;
const w4f_sweat=(x,y,d)=>`<path class="wa-drip" style="animation-delay:${d||0}s" d="M${x},${y} Q${x-5},${y+8} ${x},${y+11} Q${x+5},${y+8} ${x},${y}Z" fill="#6cc4f0" stroke="${w4f_I}" stroke-width="1.2"/>`;

